export const content: string = "# \ucf54\uc2a4\ud1a8\ub77c\ub2c8 3\uad8c \u2014 \uc2e4\uc804\ud22c\uc790\uac15\uc758 (\uc6d0\ubb38 \uc815\ub9ac\ubcf8)\n\n---\n\n## \ubaa9\ucc28\n\n1. [\ud22c\uc790\uc5d0 \uc694\ub9ac\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4](#\ud3ec\uc778\ud2b8-1)\n2. [\ub300\uc911\ub4e4\uc774 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \ub9e4\uc218\ub97c \ud558\ub294 \uc774\uc720](#\ud3ec\uc778\ud2b8-2)\n3. [\uc7a5\uae30\uc801\uc73c\ub85c \uc704\ud5d8\ud574 \ubcf4\uc5ec\ub3c4 \ub2e8\uae30\uc801\uc73c\ub85c \uc0ac\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-3)\n4. [\uc5ed\uc0ac\uc801 \uad50\ud6c8: \ud788\ud2c0\ub7ec \ub4f1\uadf9\uacfc \ud30c\ub9ac \uc99d\uad8c\uac70\ub798\uc18c](#\ud3ec\uc778\ud2b8-4)\n5. [\ud604\ub300 \uc0b0\uc5c5\uc0ac\ud68c\uc640 \uc8fc\uc2dd\uc758 \uc7a0\uc7ac\ub825](#\ud3ec\uc778\ud2b8-5)\n6. [IPO \uc99d\uac00\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc720\ub9ac\ud55c\uac00](#\ud3ec\uc778\ud2b8-6)\n7. [\uc8fc\uc2dd \uc2dc\uc138\ub294 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uac00 (3\uad6d\uba74 \uc0ac\uc774\ud074)](#\ud3ec\uc778\ud2b8-7)\n8. [\uc99d\uad8c\uc2dc\uc7a5 \ubd95\uad34 \ud6c4 \uc5b4\ub5a4 \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-8)\n9. [\uc99d\uad8c\uc2dc\uc7a5 \uac8c\uc784 \uc2dc\uc2a4\ud15c \uc804\ubc18](#\ud3ec\uc778\ud2b8-9)\n10. [\ud22c\uc790\uc790\uac00 \uc9c0\uc801\uc73c\ub85c \ud589\ub3d9\ud55c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8](#\ud3ec\uc778\ud2b8-10)\n11. [\ub300\uc911\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud558\ub294 \ub2a5\ub825](#\ud3ec\uc778\ud2b8-11)\n12. [\uc790\uc2e0\uc740 \uadf8\ub807\uac8c \ud560 \uc218 \uc788\ub098](#\ud3ec\uc778\ud2b8-12)\n13. [\uc774\ub860\uacfc \uc6d0\uce59\uc774 \uc788\ub294\ub370\ub3c4 \uc5b4\ub824\uc6b4 \uc774\uc720](#\ud3ec\uc778\ud2b8-13)\n14. [\uc21c\uc751\ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc740 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-14)\n15. [\ud6cc\ub96d\ud55c \ud22c\uc790\uc790\uac00 \uac16\ucd94\uc5b4\uc57c \ud560 \uac83](#\ud3ec\uc778\ud2b8-15)\n16. [\ud22c\uc790\uc790\ub294 \uc5b4\ub5a4 \uc9c1\uc5c5\uc5d0 \uac00\uc7a5 \uac00\uae4c\uc6b8\uae4c](#\ud3ec\uc778\ud2b8-16)\n17. [\ud22c\uc790\uc790\uc640 \uc758\uc0ac\uc758 \uacf5\ud1b5\uc810](#\ud3ec\uc778\ud2b8-17)\n18. [\ud22c\uc790\uc5d0 \ub098\uc05c \uc131\uaca9\uc774\ub780](#\ud3ec\uc778\ud2b8-18)\n19. [\uc8fc\uc2dd\ud22c\uc790\ub294 \uc5b4\ub5a4 \ub180\uc774\uc640 \uac00\uc7a5 \ube44\uc2b7\ud560\uae4c](#\ud3ec\uc778\ud2b8-19)\n20. [\ud22c\uc790\uc790\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-20)\n21. [\uc2dc\uc7a5\uc774 \uacfc\ub9e4\uc218\u00b7\uacfc\ub9e4\ub3c4 \uc0c1\ud0dc\uc778\uc9c0 \uc5b4\ub5bb\uac8c \uc54c \uc218 \uc788\ub098](#\ud3ec\uc778\ud2b8-21)\n22. [\ub300\uc911\uc774 \uacc4\uc18d \ub099\uad00\uc801\uc774\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c](#\ud3ec\uc778\ud2b8-22)\n23. [\uac70\ub798\ub7c9\uacfc \uc8fc\uac00 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubcf4\ub294 \uc2e0\ud638](#\ud3ec\uc778\ud2b8-23)\n24. [\uc774\uac83\uc740 \uc77c\ubc18\uc801\uc778 \uc758\uacac\uc778\uac00](#\ud3ec\uc778\ud2b8-24)\n25. [\uacfc\ub9e4\uc218\u00b7\uacfc\ub9e4\ub3c4\uc758 \ub2e4\ub978 \uc9d5\ud6c4](#\ud3ec\uc778\ud2b8-25)\n26. [\uadf8\ub7f0 \uacbd\uc6b0 \ud22c\uc790\uc790\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-26)\n27. [\uc678\uad6d\uc778 \ud22c\uc790\uc790\uac00 \uc0ac\uba74 \uc88b\uc9c0 \uc54a\uc740\uac00](#\ud3ec\uc778\ud2b8-27)\n28. [\uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0ac\ub3c4 \ub420\uae4c](#\ud3ec\uc778\ud2b8-28)\n29. [\uc2e0\uc6a9\uc73c\ub85c \uc99d\uad8c\uc744 \uc0c0\uc744 \ub54c \uc88b\uc740 \uacbd\ud5d8\uc774 \uc788\uc5c8\ub098](#\ud3ec\uc778\ud2b8-29)\n30. [\uadf8 \ud22c\uc790\uc758 \uacb0\uacfc\ub294 \uc5b4\ub5a0\ud588\ub294\uac00](#\ud3ec\uc778\ud2b8-30)\n31. [\uc2e0\uc6a9 \uc5c6\uc774 \ud22c\uc790\ud588\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud588\uaca0\ub294\uac00](#\ud3ec\uc778\ud2b8-31)\n32. [\uc704\ud5d8 \uc5c6\uc774\ub294 \ub3c8\uc744 \ubc8c \uc218 \uc5c6\uc9c0 \uc54a\uc740\uac00](#\ud3ec\uc778\ud2b8-32)\n33. [\uc131\uacf5\uc801\uc778 \ud22c\uc790\ub97c \uc704\ud574 \ud558\ub8e8 \uc885\uc77c \ud544\uc694\ud55c\uac00](#\ud3ec\uc778\ud2b8-33)\n34. [\uc801\uc740 \ub3c8\uc73c\ub85c \ud070 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\ub294\uac00](#\ud3ec\uc778\ud2b8-34)\n35. [\ud6cc\ub96d\ud55c \ud22c\uc790\uc790\ub77c\uba74 \uc5bc\ub9c8\ub97c \ubc8c \uc218 \uc788\ub294\uac00](#\ud3ec\uc778\ud2b8-35)\n36. [\ubaa8\ub4e0 \uc774\ub860\uc740 \ud68c\uc0c9\uc774\ub2e4](#\ud3ec\uc778\ud2b8-36)\n37. [\ub3c8\uc774 \ud22c\uc790\uc790\uc758 \ud589\ub3d9\uc744 \uacb0\uc815\ud558\ub294 \ubaa8\ub4e0 \uac83\uc778\uac00](#\ud3ec\uc778\ud2b8-37)\n38. [\ub300\uaddc\ubaa8 \ud22c\uc790\uc790\ub294 \uc704\ud5d8\ud55c \uc874\uc7ac\uc778\uac00](#\ud3ec\uc778\ud2b8-38)\n39. [\uc774\uc775 \ud639\uc740 \uc190\uc2e4\uc774 \ud074 \ub54c \ud314\uc544\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-39)\n40. [\uc2dc\uc138\ub97c \uc5b8\uc81c\ub098 \uad00\uc2ec\uc788\uac8c \ubd10\uc57c \ud558\ub098](#\ud3ec\uc778\ud2b8-40)\n41. [\uc131\uacf5\uc801\uc778 \ud22c\uc790 \ud6c4\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-41)\n42. [\ub3c5\ud559\ud55c \uc0ac\ub78c\uc758 \ub9d0\uc744 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-42)\n43. [\uc5b4\ub5a4 \uae30\uc900\uc5d0 \ub530\ub77c \uc8fc\uc2dd\uc744 \uc120\uc815\ud574\uc57c \ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-43)\n44. [\uc2e4\ud328\ud55c \ud22c\uc790\uc790\uc758 \uc758\uacac\uc740 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c\uac00](#\ud3ec\uc778\ud2b8-44)\n45. [\ud22c\uc790\uc790\ub294 \ubb34\uc5c7\uc744 \ud560 \uc904 \uc54c\uc544\uc57c \ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-45)\n46. [\ube44\ubc95\uc5d0 \uad00\ud574 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-46)\n47. [\ub300\uaddc\ubaa8 \uc720\uba85 \uae30\uc5c5\uc774 \ucd94\ucc9c\ud558\ub294 \uc885\ubaa9\uc744 \uc0ac\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-47)\n48. [\uae30\uad00 \uba38\ub2c8\ub9e4\ub2c8\uc800\uc758 \ub9e4\ub9e4 \ud589\uc704\ub97c \uc911\uc694\ud558\uac8c \uc5ec\uaca8\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-48)\n49. [\uc804\ubb38\uac00\uc758 \ucd94\ucc9c\uc740 \uc5bc\ub9c8\ub098 \uc911\uc694\ud55c\uac00](#\ud3ec\uc778\ud2b8-49)\n50. [\uae30\uc5c5 \ub0b4\ubd80\uc790\uc758 \ucd94\ucc9c\uc740 \uc5bc\ub9c8\ub098 \ubbff\uc5b4\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-50)\n51. [\uacbd\uc81c \uc804\ubb38\uac00\u00b7\uacbd\uc81c\ud559\uc790\uc758 \ub9d0\uc740 \uc5bc\ub9c8\ub098 \ubbff\uc5b4\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-51)\n52. [\uacbd\uc81c\uc640 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \ud56d\uc0c1 \uc5f0\ub3d9\ub418\ub294\uac00](#\ud3ec\uc778\ud2b8-52)\n53. [\uc0ac\uc5c5\ubcf4\uace0\uc11c\u00b7\uc8fc\uc8fc\ucd1d\ud68c \ubc1c\ud45c \ub4f1\uc774 \ucda9\ubd84\ud55c \uc815\ubcf4\uc778\uac00](#\ud3ec\uc778\ud2b8-53)\n54. [\ub300\ucc28\ub300\uc870\ud45c\u00b7\ubc30\ub2f9\uae08 \ub4f1\uc744 \uc790\uc138\ud788 \uc54c\uc544\uc57c \ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-54)\n55. [\uc804\ubb38\uac00 \ubd84\uc11d\uc740 \ub0b4\ubd80\uc790 \uc815\ubcf4\uc640 \ube44\uc2b7\ud55c\uac00](#\ud3ec\uc778\ud2b8-55)\n56. [\ud22c\uc790\uc790\uc5d0\uac8c \uac00\uc7a5 \uc704\ud5d8\ud55c \uac83\uc740 \ubb34\uc5c7\uc778\uac00](#\ud3ec\uc778\ud2b8-56)\n57. [\uac11\uc790\uae30 \ud070\ub3c8\uc774 \uc0dd\uae30\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uac00](#\ud3ec\uc778\ud2b8-57)\n58. [\uc740\ud589\uacfc \uae08\uc735\uae30\uad00\uc740 \ub300\uc911\uc5d0\uac8c \uc815\uc9c1\ud558\uc9c0 \uc54a\uc740\uac00](#\ud3ec\uc778\ud2b8-58)\n59. [\uc2dc\uc138\uac00 \ub5a8\uc5b4\uc838\uc11c \ub300\uc911\uc774 \ub3c8\uc744 \uc783\uc73c\uba74 \uacbd\uc81c\uc5d0 \ub098\uc05c\uac00](#\ud3ec\uc778\ud2b8-59)\n60. [\ubd88\uacbd\uae30 \ub54c \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud560\uae4c](#\ud3ec\uc778\ud2b8-60)\n61. [\uc65c \uacbd\uc81c\ud559\uc790\ub4e4\uc744 \uadf8\ud1a0\ub85d \ube44\ud310\ud558\ub294\uac00](#\ud3ec\uc778\ud2b8-61)\n62. [\uc790\ubcf8\uc8fc\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ub300\ud55c \ucd5c\uc885 \uacac\ud574](#\ud3ec\uc778\ud2b8-62)\n- [\ub9fa\uc74c\ub9d0](#\ub9fa\uc74c\ub9d0)\n\n---\n\n## \ub4e4\uc5b4\uac00\uba70\n\n\uac15\uc758 \ud50c\ub7ab\ud3fc\uc5d0\uc11c \ud22c\uc790 \uacbd\ub825 30\ub144\uc774 \ucc44 \uc548 \ub418\ub294 \ubd84\ub4e4\uc758 \uc8fc\uc2dd\ud22c\uc790 \uac15\uc758\ub97c \ub4e3\ub294\ub370 \ucd5c\uc18c 10\ub9cc \uc6d0\uc740 \uacb0\uc81c\ud574\uc57c \ud55c\ub2e4. \uadf8\ub7f0\ub370 80\ub144 \ud22c\uc790 \uacbd\ub825\uc758 \ud22c\uc790 \ub300\uac00\uc5d0\uac8c \uc2e4\uc804\ud22c\uc790 \uac15\uc758\ub97c \ub4e3\ub294 \ub370 12,000\uc6d0\uc774\ub77c\uba74 \ubbff\uc5b4\uc9c0\uaca0\ub294\uac00. \ud22c\uc790 \uacbd\ub825\uc5d0 \ube44\ub840\ud574\uc11c \uac15\uc758\ub8cc\ub97c \ucc45\uc815\ud55c\ub2e4\uba74 \uc774 \ucc45\uc758 \uac00\uaca9\uc740 26\ub9cc 6,666\uc6d0\uc774 \ub418\uc5b4\uc57c \ud55c\ub2e4.\n\n\ucc45\uc73c\ub85c \ucd9c\ud310\ub418\uc5c8\uae30\uc5d0 \uc800\ub834\ud55c \uac00\uaca9\uc73c\ub85c \uc591\uc9c8\uc758 \uac15\uc758\ub97c \ubcfc \uc218 \uc788\ub2e4. \ubc11\uc904\uc744 \uadf8\uc5b4\uac00\uba70 \ub450\uace0\ub450\uace0 \uc77d\uc5b4\ubcf4\uc2dc\uae30\ub97c \uac15\ub825\ud788 \ucd94\ucc9c\ud55c\ub2e4. \uadf8\ub9cc\ud55c \uac00\uce58\uac00 \ucda9\ubd84\ud55c \ucc45\uc774\ub2e4.\n\n\uc624\ub298 \uc2dc\uac04\uc740 \ud22c\uc790\uacc4\uc758 \uc804\uc124 \uc559\ub4dc\ub808 \ucf54\uc2a4\ud1a8\ub77c\ub2c8\uc758 \ucd1d\uc11c \uc911 \ub9c8\uc9c0\ub9c9 \uad8c\uc778 \u300e\uc2e4\uc804\ud22c\uc790\uac15\uc758\u300f\ub97c 62\uac1c\uc758 \ud3ec\uc778\ud2b8\ub85c \uc694\uc57d\ud558\uc5ec \ub9d0\uc500\ub4dc\ub9ac\ub824 \ud55c\ub2e4. \uc624\ub298 \uc601\uc0c1\uc758 \ud575\uc2ec\uc740 7\ubc88\ubd80\ud130 22\ubc88 \ud3ec\uc778\ud2b8\uae4c\uc9c0\ub2e4. \ud2b9\ud788 \ud604\uc7ac \uc6b0\ub9ac\uac00 \ucc98\ud55c \uc2dc\uc7a5 \uc0c1\ud669\uc5d0 \ub300\ucc98\ud558\ub294 \ubc95\uacfc, \ud22c\uc790\uc790\ub77c\uba74 \ub204\uad6c\ub098 \uace0\ubbfc\ud560 \uc218 \uc788\ub294 \uac83\ub4e4\uc5d0 \ub300\ud55c \ud604\uc790\uc758 \uc9c0\ud61c\ub97c \uc5bb\uc5b4\uac08 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 1\n\n**\ud22c\uc790\uc5d0 \uc694\ub9ac\ubc95\uc744 \uc54c\ub824\ub4dc\ub9bd\ub2c8\ub2e4**\n\n**\uc131\uacf5\ud558\ub824\uba74 \ucd94\ucc9c \uc885\ubaa9\uc744 \ub530\ub77c \ud558\uc9c0 \ub9d0\uace0 \uc2a4\uc2a4\ub85c \uc544\uc774\ub514\uc5b4\uc640 \uc758\uacac\uc744 \uac00\uc838\uc57c \ud55c\ub2e4.** \ub2e4\uc2dc \ub9d0\ud574 \uc2a4\uc2a4\ub85c \uc0dd\uac01\ud574\uc57c \ud558\uace0, \ud6cc\ub96d\ud558\uace0 \uacbd\ud5d8 \ub9ce\uc740 \uc5b4\ubd80\uac00 \uc0dd\uc120\uc744 \uc7a1\ub4ef\uc774 \uc2a4\uc2a4\ub85c \ucd94\ucc9c \uc885\ubaa9\uc744 \ub9cc\ub4e4\uc5b4\uc57c \ud55c\ub2e4. \uc8fc\uc2dd\uc744 \uc0b4\uc9c0, \uc544\ubb34 \ud589\ub3d9\ub3c4 \ud558\uc9c0 \uc54a\uc744\uc9c0 \uacb0\uc815\ud560 \uc218 \uc788\uc73c\ub824\uba74 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ub4f1\ub77d \uc6b4\ub3d9 \uba54\ucee4\ub2c8\uc998\uc744 \uc774\ud574\ud574\uc57c \ud55c\ub2e4.\n\n> \ub098\ub294 \uc774 \ucc45\uc5d0\uc11c \uc99d\uad8c\uc2dc\uc7a5\uc744 \uc870\ub9dd\ud558\uace0, \ub098\uc758 \uba85\uc81c\uc640 \ubc29\ubc95\uc744 \uc544\uc8fc \uac04\ub2e8\ud558\uace0 \ubcf5\uc7a1\ud558\uc9c0 \uc54a\uac8c \uc124\uba85\ud558\ub824\uace0 \ud55c\ub2e4. \ub0b4 70\ub144\uac04\uc758 \uacbd\ud5d8 \uc18d\uc5d0\uc11c \ub300\ub2f5\uc744 \ucc3e\uc558\ub2e4. \uc774 \ucc45\uc740 \ub098\uc758 \uacbd\ud5d8\uc758 \uc9d1\uc57d\uccb4\uc774\ub2e4.\n\n\uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc77c\uc5b4\ub0a0 \uc218 \uc788\ub294 \uc0ac\uac74\uc740 \uc218\uc5c6\uc774 \ub9ce\ub2e4. \uadf8 \ubaa8\ub4e0 \uacbd\uc6b0\ub97c \ub2e4 \ubd84\uc11d\ud558\ub294 \uac83\uc740 \ubd88\uac00\ub2a5\ud558\ub2e4. **\uc644\uc131\ub41c \uc694\ub9ac\uac00 \uc544\ub2c8\ub77c \uc694\ub9ac\ubc95\uc744 \uc18c\uac1c\ud568\uc73c\ub85c\uc368 \uc5ec\ub7ec\ubd84\ub4e4\uc774 \ub9c8\uc74c\uc5d0 \ub4dc\ub294 \uc694\ub9ac\ub97c \uc9c1\uc811 \ud574 \uba39\uc744 \uc218 \uc788\ub3c4\ub85d \ud558\ub824\uace0 \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 2\n\n**\ub300\uc911\ub4e4\uc774 \ubb34\uc758\uc2dd\uc801\uc73c\ub85c \ub9e4\uc218\ub97c \ud558\ub294 \uc774\uc720**\n\n\ub300\uc911\uc740 \uc2dc\uc138\uac00 \uc62c\ub77c\uac00\uba74 \uc8fc\uc2dd\uc744 \uc0ac\uace0, \uc2dc\uc138\uac00 \ub5a8\uc5b4\uc9c0\uba74 \ud310\ub2e4. **\uc8fc\uc2dd\uc774 \uc774\ubbf8 \uc5bc\ub9c8\ub098 \uc62c\ub790\ub294\uc9c0 \ubcf4\uc5ec\uc8fc\uace0 \uc55e\uc73c\ub85c \ub354 \uc624\ub97c \uac70\ub77c\ub294 \ud655\uc2e0\uc744 \uc904 \uc218 \uc788\ub2e4\uba74, \ub300\uc911\uc5d0\uac8c \uc8fc\uc2dd\uc744 \ud30c\ub294 \uc77c\uc740 \uadf8\uc57c\ub9d0\ub85c \uc2dd\uc740 \uc8fd \uba39\uae30\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 3\n\n**\uc7a5\uae30\uc801\uc73c\ub85c \uc704\ud5d8\ud574 \ubcf4\uc5ec\ub3c4 \ub2e8\uae30\uc801\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud560\uae4c**\n\n\uc544\ub2c8\ub2e4. **\uc5b4\ub5a4 \uacbd\uc6b0\uc5d0\ub3c4 \uadf8\ub798\uc11c\ub294 \uc548 \ub41c\ub2e4.** \ub2ec\uc774 \ub05d\ubd80\ubd84\uc5d0 \uaebe\uc5ec \uc788\ub294\ub370 \uad73\uc774 \uadf8 \ub2e4\ub9ac\uc5d0 \uc9c4\uc785\ud574\uc57c \ud558\ub294\uac00\ub77c\ub294 \uc9c8\ubb38\uacfc \uac19\uc740 \ub9d0\uc774\ub2e4. \uad6d\ub0b4\uc678 \uc0c1\ud669\uc774 \uc99d\uc2dc\uc5d0 \uc88b\uc9c0 \uc54a\uac8c \ub420 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ud55c\ub2e4\uba74, \uc774 \uc704\ud5d8\uc744 \ubbf8\ub9ac \uacc4\uc0b0\uc5d0 \ub123\uc5b4\uc57c \ud55c\ub2e4. \uc544\uc9c1 \uc2dc\uac04\uc774 \ub9ce\ub2e4\ub294 \uadfc\uac70\ub85c \uc774 \uc704\ud5d8\uc744 \uac04\uacfc\ud574\uc11c\ub294 \uc548 \ub41c\ub2e4.\n\n\uc774\uc640 \uad00\ub828\ub41c \uacbd\ud5d8\uc774 \uc544\uc9c1\ub3c4 \uc0dd\uc0dd\ud558\ub2e4. 1930\ub144\ub300\uc5d0 \ub098\ub294 \ud30c\ub9ac \uc99d\uad8c\uac70\ub798\uc18c\uc5d0\uc11c \ud22c\uc790\ub97c \ud588\ub2e4. \ud558\uc9c0\ub9cc \uc791\uc804 \uc138\ub825\uc774 \uc8fc\uac00\ub97c \uc62c\ub9ac\ub824\uace0 \uc870\uc791\ud588\uae30 \ub54c\ubb38\uc5d0 \uc8fc\uac00\ub294 \uacc4\uc18d \uc62c\ub77c\uac14\ub2e4. \uadf8\ub54c \ud788\ud2c0\ub7ec\uac00 \uc120\uac70\uc5d0\uc11c \ud06c\uac8c \uc774\uacbc\ub2e4. \uac08\uc0c9 \uc720\ub2c8\ud3fc\uc744 \uc785\uace0 \ub098\uce58 \uc644\uc7a5\uc744 \ucc2c 67\uba85\uc758 \uc758\uc6d0\ub4e4\uc774 \uc81c\uad6d\uc758\ud68c\ub85c \ub4e4\uc5b4\uac14\ub2e4. \ub9ce\uc740 \uc774\ub4e4\uc5d0\uac8c \uc774\ub294 \ub054\ucc0d\ud55c \uc0ac\uac74\uc774\uc5c8\ub2e4. \uadf8\ub7f0\ub370 \ud30c\ub9ac \uc99d\uad8c\uac70\ub798\uc18c\uc5d0\uc11c\ub294 \uc774\uc5d0 \uc5b4\ub5a4 \uc601\ud5a5\ub3c4 \ubc1b\uc9c0 \uc54a\uc558\ub2e4. \ub098\ub294 \ub3d9\ub8cc\ub4e4\uc5d0\uac8c \ud3c9\ud654\ub97c \uc704\ud611\ud560 \uc218 \uc788\ub294 \uc704\uc778\uc774 \uad8c\ub825\uc744 \uc7a1\uc558\ub294\ub370 \uc774\ub807\uac8c \uc8fc\uac00\uac00 \uc0c1\uc2b9\ud558\ub2e4\ub2c8 \ubbff\uc744 \uc218 \uc5c6\ub2e4\uace0 \ubc18\ubcf5\ud574\uc11c \ub9d0\ud588\ub2e4. \uadf8\ub7ac\ub354\ub2c8 \ub3d9\ub8cc\ub4e4\uc740 \uc774\ub807\uac8c \ub9d0\ud588\ub2e4.\n\n> \"\uc544\ub2c8, \ub3c5\uc77c\uc5d0\uc11c \uc77c\uc5b4\ub098\ub294 \uc77c\uc774 \uc6b0\ub9ac\uc640 \ubb34\uc2a8 \uc0c1\uad00\uc774\uc57c. \uc5ec\uae30\ub294 \ud504\ub791\uc2a4\ub77c\uace0.\"\n\n\ub098\ub294 \uc774\ub7f0 \ubc18\uc751\uc774 \uc815\ub9d0 \ub180\ub77c\uc6e0\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 4\n\n**\uc5ed\uc0ac\uc801 \uad50\ud6c8: \ud788\ud2c0\ub7ec \ub4f1\uadf9\uacfc \ud30c\ub9ac \uc99d\uad8c\uac70\ub798\uc18c**\n\n\ub098\uc911\uc5d0 \ud30c\ub9ac\uc758 \uc8fc\uc2dd\ud22c\uc790\uc790\ub4e4\uc740 \ud788\ud2c0\ub7ec\uc758 \ub4f1\uadf9\uc774 \uc2ec\uac01\ud55c \ub274\uc2a4\ub77c\ub294 \uac83\uc744 \uc54c\uac8c \ub418\uc5c8\ub2e4. \uc8fc\uac00\ub294 \ud3ed\ub77d\ud588\uace0 \ub098\ub294 \ud070 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\uc5c8\ub2e4.\n\n**\uc694\ucee8\ub300, \ud22c\uc790\uc790\ub294 \uc790\uae30 \ucf54\uc55e\ub9cc \ubcf4\uc9c0 \ub9d0\uace0 \ud56d\uc0c1 \uc55e\uc744 \ub0b4\ub2e4\ubd10\uc57c \ud55c\ub2e4. \uc608\uc0c1\uc5d0 \ub300\ud55c \uc608\uc0c1\uc744 \ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4.** \uc790\ub3d9\ucc28 \uc6b4\uc804\uc744 \ubc30\uc6b8 \ub54c \uc6b4\uc804 \uc120\uc0dd\uc740 \ud56d\uc0c1 \uc774\ub807\uac8c \ub9d0\ud588\ub2e4.\n\n> \"\ucc28 \ubc14\ub85c \uc55e\uc5d0 \ubb34\uc5c7\uc774 \uc788\ub294\uc9c0 \ubcf4\uc9c0 \ub9d0\uace0, \ud56d\uc0c1 100m, 200m \uc55e\uc744 \ubd10\ub77c.\"\n\n\uc8fc\uc2dd \ud22c\uc790\ub3c4 \ub9c8\ucc2c\uac00\uc9c0\ub2e4. \uc8fc\uac00\uac00 \ub0b4\uc77c \ud639\uc740 \ubaa8\ub808 \uc624\ub97c\uc9c0 \uc0dd\uac01\ud558\uc9c0 \ub9d0\uace0, \uc55e\uc73c\ub85c \ubb34\uc2a8 \uc77c\uc774 \uc0dd\uae38\uc9c0, \ub2e4\uc74c \ub2ec\uacfc \ub0b4\ub144\uc5d0 \uc5b4\ub5bb\uac8c \ub420\uc9c0 \uc0dd\uac01\ud558\ub77c. 3~4\ub144 \ud6c4\uc5d0 \uc798\ub420 \uae30\uc5c5\uc744 \uace8\ub77c\uc11c \uadf8 \uae30\uc5c5\uc5d0 \ub300\ud574 \ucda9\ubd84\ud788 \uacf5\ubd80\ud55c \ud6c4 \ud655\uc2e0\uc774 \uc130\ub2e4\uba74 \uc758\ubbf8 \uc788\ub294 \uae08\uc561\uc744 \uc9d1\uc911 \ud22c\uc790\ud558\ub77c.\n\n---\n\n## \ud3ec\uc778\ud2b8 5\n\n**\ud604\ub300 \uc0b0\uc5c5\uc0ac\ud68c\uc640 \uc8fc\uc2dd\uc758 \uc7a0\uc7ac\ub825**\n\n\uace0\ub3c4\uc758 \ud14c\ud06c\ub2c9\uc744 \uc0ac\uc6a9\ud558\uba70 \ud56d\uc0c1 \ud601\uc2e0\uc744 \uc694\uad6c\ud558\ub294 \ud604\ub300 \uc0b0\uc5c5\uc0ac\ud68c\uc5d0\ub294 \ub9ce\uc740 \uc790\ubcf8\uc744 \ud544\uc694\ub85c \ud55c\ub2e4. **\uadf8\ub798\uc11c \uc8fc\uc2dd\uc758 \uc7a0\uc7ac\ub825\uc774 \ud3ed\ubc1c\uc801\uc73c\ub85c \ucee4\uc9c8 \uac00\ub2a5\uc131\uc774 \uc788\ub2e4.** \uae30\uc5c5\uc5d0\uac8c\ub294 \uc8fc\uc2dd\uc774 \uc0ac\uc5c5 \ud655\uc7a5\uc758 \ud1a0\ub300\uc774\ub2e4. \uc8fc\uc2dd\ud22c\uc790\ub294 \uacbd\uc81c\ubc1c\uc804\uc758 \ud544\uc218\uc801 \uc694\uc18c\uc774\uba70, \uadf8\ub7f0 \uc8fc\uc2dd\ud22c\uc790\ub97c \uac00\ub2a5\ud558\uac8c \ud558\ub294 \uc99d\uad8c \uc2dc\uc2a4\ud15c \uc5ed\uc2dc \ubc18\ub4dc\uc2dc \uc874\uc7ac\ud574\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 6\n\n**IPO \uc99d\uac00\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc720\ub9ac\ud55c\uac00**\n\n\ub9ce\uc740 \uae30\uc5c5\uc774 \uc8fc\uc2dd\uc2dc\uc7a5\uc73c\ub85c \ub4e4\uc5b4\uc640 \uc0c8\ub85c\uc6b4 \uc8fc\uc2dd\uc774 \ub9ce\uc544\uc9c0\uba74 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc720\ub9ac\ud560\uae4c? \uadf8\ub807\uc9c0 \uc54a\ub2e4. **\ubc18\ub300\ub2e4.**\n\n\uc218\ub9ce\uc740 \uc0c8 \uc8fc\uc2dd\uc774 \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \ub3d9\uc548 \uc5b8\ub860\uacfc \uc120\uc804\uc744 \ud1b5\ud574 \uc99d\uad8c\uc2dc\uc7a5\uc758 \ubd84\uc704\uae30\ub97c \ub099\uad00\uc801\uc73c\ub85c \ub9cc\ub4e0\ub2e4. \ub099\uad00\uc801\uc77c\uc218\ub85d \ub300\uc911\uc740 \ube68\ub9ac \uc0c8 \uc8fc\uc2dd\uc744 \uc0bc\ud0a8\ub2e4. \ud558\uc9c0\ub9cc \ub099\uad00\uc801\uc778 \ubd84\uc704\uae30\uac00 \uc0ac\ub77c\uc9c0\uba74 \uadf8\uc5d0 \ub300\ud55c \ubc18\uc751\ub3c4 \uadf8\ub9cc\ud07c \uaca9\ub82c\ud558\uac8c \ub098\ud0c0\ub09c\ub2e4. \uc774\ub7f0 \ud558\ub77d\uc740 \uc0dd\uac01\ud588\ub358 \uac83\ubcf4\ub2e4 \uc2ec\uac01\ud560 \uc218 \uc788\ub2e4. \ucd5c\uace0\uc758 \uacbd\uc81c \uc804\ubb38\uac00\uc870\ucc28\ub3c4 \uadf8\uc800 \ub9dd\uc5f0\uc790\uc2e4\ud560 \ubfd0 \uc544\ubb34\uac83\ub3c4 \ud560 \uc218 \uc5c6\ub2e4. **\uc774 \uc0c1\ud669\uc5d0\uc11c \ub2e4\uac00\uc62c \uc0ac\ud0dc\uc5d0 \ubbf8\ub9ac \uc900\ube44\ud558\uace0 \uadf8\uc5d0 \ub530\ub77c \ud589\ub3d9\ud558\ub294 \uac83\uc774 \ucd5c\uace0\uc758 \ub300\ucc98 \uae30\uc220\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 7\n\n**\uc8fc\uc2dd \uc2dc\uc138\ub294 \uc5b4\ub5bb\uac8c \uc6c0\uc9c1\uc774\ub294\uac00 (3\uad6d\uba74 \uc0ac\uc774\ud074)**\n\n\uc8fc\uac00\ub294 \ub2e4\uc74c\uacfc \uac19\uc774 \uc6c0\uc9c1\uc778\ub2e4.\n\n**[\ud558\ub77d\uc7a5 \u2192 \ubc14\ub2e5]**\n\n\uc99d\uad8c\uc2dc\uc7a5\uc774 \ubc14\ub2e5\uc5d0 \uc640 \uc788\uace0 \uc8fc\uac00\ub294 \uc0c1\uc2b9\uc7a5\uc744 \uacaa\uc740 \ud6c4 \uc544\uc8fc \ud06c\uac8c \ub5a8\uc5b4\uc838 \uc788\ub2e4. \uc774\uc720\ub294 \uae08\ub9ac\uac00 \uc624\ub974\uace0 \uc2dc\uc911\uc5d0 \uc720\ub3d9 \uc790\uae08\uc774 \uc5c6\uc5b4\uc84c\uae30 \ub54c\ubb38\uc774\ub2e4. \ud22c\uc790\uc790\ub4e4 \uc0ac\uc774\uc5d0\ub294 \uacbd\uc81c\uc801 \ubc1c\uc804 \ubc0f \uae30\uc5c5\uc758 \uc774\uc724\uacfc \uad00\ub828\ud574 \ube44\uad00\uc801\uc778 \uc0dd\uac01\uc774 \ud37c\uc838 \uc788\ub2e4. **\ub098\uc05c \ub274\uc2a4\uc5d0\ub3c4 \uc8fc\uac00\uac00 \ub354 \uc774\uc0c1 \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\ub294\ub2e4\uba74, \uc774\ub294 \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \uc8fc\uc2dd\uc744 \ubaa8\ub450 \ud314\uc544 \ubc84\ub838\ub2e4\ub294 \uc99d\uac70\uc774\ub2e4.** \uc774\uc724\uc774 \uc0dd\uac01\ud588\ub358 \uac83\ubcf4\ub2e4 \ub098\uc058\uc9c0 \uc54a\ub2e4\ub294 \ub274\uc2a4\uac00 \ub4e4\ub824\uc624\uace0, \uc911\uc559\uc740\ud589\uc740 \ub192\uc740 \uae08\ub9ac \ub54c\ubb38\uc5d0 \ubc14\ub2e5\uc73c\ub85c \ub5a8\uc5b4\uc9c4 \uacbd\uae30\ub97c \ub2e4\uc2dc \ud65c\uc131\ud654\uc2dc\ud0a4\uae30 \uc704\ud574 \uae08\ub9ac\ub97c \ub0b4\ub9b0\ub2e4.\n\n**[\uc81c1\uad6d\uba74: \uc870\uc815 \uad6d\uba74]**\n\n\uae08\ub9ac\uac00 \ud558\ub77d\ud558\uba74 \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294 \ub3c8\uc758 \uc591\uc774 \ub9ce\uc544\uc9c4\ub2e4. \ub178\ub828\ud55c \ud504\ub85c \ud22c\uc790\uc790\uc640 \uc120\uad6c\uc790\ub4e4\uc774 \uc8fc\uc2dd\uc744 \uc0ac\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc8fc\uac00\uac00 \uc62c\ub77c\uac00\uba74\uc11c \ube44\uad00\uc801\uc778 \ubd84\uc704\uae30\ub294 \uc810\uc810 \uc57d\ud574\uc9c4\ub2e4. \uc774\ub85c \uc778\ud574 \uc0c8\ub85c\uc6b4 \ud22c\uc790\uc790\uac00 \uc2dc\uc7a5\uc5d0 \ub4e4\uc5b4\uc624\uace0 \uc8fc\uac00\ub294 \ub2e4\uc2dc \uc62c\ub77c\uac04\ub2e4. \ube44\uad00\uc8fc\uc758\uac00 \uc57d\ud574\uc9c0\uace0 \u2192 \uc0c8\ub85c\uc6b4 \ub9e4\uc218\uc790\uac00 \ub4f1\uc7a5\ud558\uace0 \u2192 \uc8fc\uac00\uac00 \uc62c\ub77c\uac00\uace0 \u2192 \ub099\uad00\uc801\uc774 \ub418\uace0 \u2192 \uc8fc\uac00\uac00 \ub2e4\uc2dc \uc62c\ub77c\uac00\ub294 \uc77c\ub828\uc758 \uacfc\uc815\uc774 \ubc18\ubcf5\ub41c\ub2e4. \uc804\uc5d0 \ub108\ubb34 \ube44\uad00\uc801\uc778 \ubd84\uc704\uae30\uac00 \ud33d\ubc30\ud574 \uc8fc\uac00\uac00 \uac00\uce58\ubcf4\ub2e4 \ud6e8\uc52c \ubc11\uc73c\ub85c \ub5a8\uc5b4\uc84c\ub2e4\uac00 \ud604\uc2e4\uc801\uc778 \uc218\uc900\uc5d0 \ub3c4\ub2ec\ud558\ub294 \uc774 \uccab \ubc88\uc9f8 \uad6d\uba74\uc744 **\uc870\uc815 \uad6d\uba74**\uc774\ub77c\uace0 \ubd80\ub978\ub2e4.\n\n**[\uc81c2\uad6d\uba74: \ub3d9\ud589 \uad6d\uba74]**\n\n\uae08\ub9ac\uac00 \ub5a8\uc5b4\uc9c0\uace0 \uc774\uc724\uc774 \uc99d\uac00\ud558\uace0 \uc788\ub2e4\ub294 \ub274\uc2a4\uac00 \ub4e4\ub824\uc624\uae30 \uc2dc\uc791\ud55c\ub2e4. \uc8fc\uac00\ub294 \uc774 \uc0c8\ub85c\uc6b4 \ub099\uad00\uc801\uc778, \uacbd\uc81c\uc801\uc73c\ub85c \uadfc\uac70 \uc788\ub294 \ubc1c\uc804\uacfc \ubc1c\uc744 \ub9de\ucdb0 \ud568\uaed8 \uc11c\uc11c\ud788 \uc62c\ub77c\uac04\ub2e4. \uc774 \uad6d\uba74\uc744 **\ub3d9\ud589 \uad6d\uba74**\uc774\ub77c\uace0 \ubd80\ub978\ub2e4. \uc8fc\uac00\uac00 \uc804\uccb4 \ubc1c\uc804\uacfc \ub3d9\ud589\ud558\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n**[\uc81c3\uad6d\uba74: \uacfc\uc7a5 \uad6d\uba74 \u2014 \uc0c1\uc2b9]**\n\n\uc810\uc810 \ub354 \ub9ce\uc740 \ud22c\uc790\uc790\uc640 \ud22c\uae30\uafbc\uc774 \uc2dc\uc7a5\uc73c\ub85c \ubab0\ub824\uc628\ub2e4. \uc704\ud5d8\uc740 \uc804\ud600 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \ub05d\uc5c6\ub294 \ub099\uad00\uc8fc\uc758\uac00 \ud33d\ubc30\ud558\ub2e4. \ub9ce\uc740 \uc774\ub4e4\uc774 \ub098\ubc29\uc774 \ubd88\uc18d\uc73c\ub85c \ub6f0\uc5b4\ub4e4\ub4ef\uc774 \uac8c\uc784\uc5d0 \ub6f0\uc5b4\ub4e0\ub2e4. \uc0c1\uc2b9\uc740 \ub610 \ub2e4\ub978 \uc0c1\uc2b9\uc744 \ub0b3\ub294\ub2e4. **\uc774\ub97c \uacfc\uc7a5 \uad6d\uba74\uc774\ub77c\uace0 \ubd80\ub978\ub2e4.**\n\n> \ub098\ubb34\ub294 \ud558\ub298 \ub05d\uae4c\uc9c0 \uc790\ub77c\uc9c0 \uc54a\ub294\ub2e4.\n\n\ubaa8\ub4e0 \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc8fc\uc2dd\uc744 \ud3ec\ud654 \uc0c1\ud0dc\uae4c\uc9c0 \uc0ac\ub4e4\uc774\uace0, \ub3c8\uc774 \uc5c6\uc73c\uba74 \uc2e0\uc6a9\uc73c\ub85c \uc0b0\ub2e4. \uc740\ud589\uc740 \uc720\ub3d9 \uc790\uae08\uc744 \uc544\uc8fc \ub9ce\uc774 \uac16\uace0 \uc788\uc73c\ubbc0\ub85c \uc720\ub9ac\ud55c \uc870\uac74\uc758 \ub3c8\uc744 \ube4c\ub824\uc8fc\uace0 \uc774\ub85c \uc778\ud574 \uc8fc\uc2dd \ub9e4\uc218\ub97c \uc790\uadf9\ud55c\ub2e4. \uc870\uc2ec\uc2a4\ub7fd\uac8c \uae08\ub9ac\ub97c \uc62c\ub9ac\uace0 \uc720\ub3d9 \uc790\uae08\uc744 \uc904\uc774\uae30 \uc2dc\uc791\ud55c\ub2e4.\n\n\uc8fc\uc2dd \ubcf4\uc720\uc790\ub294 \ub354 \ub192\uc740 \uac00\uaca9\uc5d0 \uc8fc\uc2dd\uc744 \ud314 \uc0c8\ub85c\uc6b4 \uad6c\ub9e4\uc790\ub97c \uae30\ub2e4\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc911\uc559\uc740\ud589\uc758 \uc0c8\ub85c\uc6b4 \ud1b5\ud654 \uc815\ucc45 \uacb0\uacfc \uc0c8\ub85c\uc6b4 \ub3c8\uc774 \uc99d\uc2dc\ub85c \ud758\ub7ec \ub4e4\uc5b4\uc624\uc9c0 \uc54a\ub294\ub2e4. **\uc8fc\uac00\ub294 \uc774\uc81c \uc774\uc724\uacfc \ubc30\ub2f9\uae08 \uc99d\uac00 \ub4f1 \uc88b\uc740 \uacbd\uc81c \ub274\uc2a4\uc5d0\ub3c4 \ubd88\uad6c\ud558\uace0 \ub354 \uc774\uc0c1 \uc624\ub974\uc9c0 \uc54a\ub294\ub2e4.**\n\n**[\ud558\ub77d \uc81c1\uad6d\uba74]**\n\n\uba87\uba87 \ud22c\uc790\uc790\uac00 \ub354 \ub192\uc740 \uac00\uaca9\uc5d0 \uc8fc\uc2dd\uc744 \ud314 \uc218 \uc5c6\uac8c \ub418\uc790 \uc2dc\uc7a5\uc5d0\uc11c \ub098\uc624\ub824\uace0, \ud639\uc740 \ub3c8\uc774 \ud544\uc694\ud574\uc11c \uc8fc\uc2dd\uc744 \ud310\ub2e4. \ucc98\uc74c\uc5d0\ub294 \ucc9c\ucc9c\ud788, \uc870\uae08\uc529 \ud314\uc9c0\ub9cc \uc774\ub85c \uc778\ud574 \uc8fc\uac00\ub294 \ub5a8\uc5b4\uc9c4\ub2e4.\n\n**[\ud558\ub77d \uc81c2\uad6d\uba74]**\n\n\uc810\ucc28 \uc774\uc724 \uac10\uc18c, \ubc30\ub2f9\uae08 \uac10\uc18c \ub4f1\uc758 \ub098\uc05c \ub274\uc2a4\uac00 \ub4e4\ub9ac\uace0 \uc8fc\uac00\uac00 \ub354 \ub5a8\uc5b4\uc9c4\ub2e4.\n\n**[\ud558\ub77d \uc81c3\uad6d\uba74: \uacfc\uc7a5 \uad6d\uba74 \u2014 \ud558\ub77d]**\n\n\ub5a8\uc5b4\uc9c0\ub294 \uc8fc\uac00\uc640 \ub098\uc05c \ub274\uc2a4\ub294 \uc0ac\ub78c\ub4e4\uc744 \ub450\ub835\uac8c \ub9cc\ub4e4\uace0, \uc8fc\uac00 \ud558\ub77d \u2192 \ub450\ub824\uc6c0 \u2192 \uc8fc\uc2dd \ub9e4\ub3c4 \u2192 \uc8fc\uac00 \ud558\ub77d\uc774\ub77c\ub294 \uc77c\ub828\uc758 \uacfc\uc815\uc774 \uc2dc\uc791\ub41c\ub2e4. \ub9c8\uc9c0\ub9c9\uc73c\ub85c \ubaa8\ub4e0 \uac83\uc744 \ub358\uc9c0\ub294 \ud22c\ub9e4 \ud604\uc0c1\uc774 \uc77c\uc5b4\ub09c\ub2e4. \uc8fc\uac00\uac00 \ub300\uc911\uc758 \uc2ec\ub9ac\uc801 \uc555\ub825\uc5d0 \uc758\ud574 \uac00\uce58\ubcf4\ub2e4 \ud6e8\uc52c \ub354 \uae4a\uc774 \ub5a8\uc5b4\uc9c0\uae30 \ub54c\ubb38\uc5d0 \uacfc\uc7a5 \uad6d\uba74\uc774\ub77c\uace0 \ubd80\ub978\ub2e4.\n\n**\uc694\ucee8\ub300, \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc810\uc810 \ub354 \ub0ae\uc740 \uac00\uaca9\uc5d0 \uc8fc\uc2dd\uc744 \ud314\uace0, \uc18c\uc2e0\ud30c\ub294 \uc774\ub97c \uc0ac\ub4e4\uc778\ub2e4.** \ud22c\uc790\uc790\uac00 \ub178\ub828\ud574\uc9c8\uc218\ub85d \uc77c\ubc18\uc801\uc778 \ucd94\uc138\uc640 \ubc18\ub300\ub85c \ud589\ub3d9\ud55c\ub2e4. \ud558\ub77d \uad6d\uba74\uc758 \uc138 \ubc88\uc9f8 \uacfc\uc7a5 \uad6d\uba74\uc5d0\uc11c \uc774\ubbf8 \ub9e4\uc218\ub97c \uc2dc\uc791\ud558\uace0, \uc0c1\uc2b9 \uc6b4\ub3d9\uc758 \uccab \ubc88\uc9f8 \uad6d\uba74\uc5d0\uc11c\ub3c4 \ub9e4\uc218\ub97c \ud55c \ub2e4\uc74c \uadf8\ub300\ub85c \uc9c4\ud589\ub418\ub3c4\ub85d \ub0b4\ubc84\ub824 \ub454\ub2e4. \uadf8 \ud6c4 \uc0c1\uc2b9 \uc6b4\ub3d9\uc774 \uc815\uc810\uc5d0 \ub2ec\ud558\uba74 \uc11c\uc11c\ud788 \ud314\uae30 \uc2dc\uc791\ud55c\ub2e4.\n\n> \ube44\uad00\uc801\uc778 \ub099\uad00 \ud22c\uc790\uc790\uac00 \ub099\uad00\uc801\uc774 \ub418\uba74 \uc774\ub294 \uc2dc\uc7a5\uc5d0\uc11c \ub098\uc640\uc57c \ud55c\ub2e4\ub294 \uc2e0\ud638\uc774\ub2e4. \uadf8 \ubc18\ub300\ub3c4 \uc131\ub9bd\ud55c\ub2e4. \uc5f4\uc815\uc801\uc778 \ub099\uad00\uc8fc\uc758\uc790\uac00 \ube44\uad00\uc801\uc774 \ub418\uba74 \uc774\ub54c\uac00 \uc2dc\uc7a5\uc5d0 \ub4e4\uc5b4\uac08 \ub54c\uc774\ub2e4.\n\n**\uc804\uccb4 \uc0ac\uc774\ud074\uc5d0\uc11c 3\ubd84\uc758 2\ub294 \ucd94\uc138\uc640 \ubc18\ub300\ub85c \ud589\ub3d9\ud558\uace0 3\ubd84\uc758 1\uc740 \ucd94\uc138\uc640 \ud568\uaed8 \uac00\uc57c \ud55c\ub2e4.** \ud558\uc9c0\ub9cc \uc774\ub807\uac8c \ud558\ub294 \uac83\uc740 \ub9e4\uc6b0 \uc5b4\ub835\uace0 \uc544\uc8fc \uc5c4\uaca9\ud55c \uaddc\uc728\uc744 \uc694\uad6c\ud55c\ub2e4. \uc8fc\uc2dd\uc2dc\uc7a5 \ucc38\uc5ec\uc790\uc758 \ub300\ubd80\ubd84, \uc989 90%\ub294 \ud56d\uc0c1 \ub611\uac19\uc740 \uc0dd\uac01\uc744 \ud558\uae30 \ub54c\ubb38\uc5d0 \uac01 \uac1c\uc778\uc774 \uc804\uccb4 \uc758\uacac\uacfc \uc790\uc2e0\uc744 \ubd84\ub9ac\ud55c\ub2e4\ub294 \uac83\uc740 \ub9e4\uc6b0 \uc5b4\ub824\uc6b4 \uc77c\uc774\ub2e4.\n\n\uc0c1\uc2b9\uc7a5\uc5d0\uc11c\ub294 \uc989\uc2dc \ud314\uc9c0 \ub9d0\uace0 \uc5b4\ub290 \uc815\ub3c4 \ucd94\uc138\uc640 \ud568\uaed8 \uac00\uace0, \ud558\ub77d\uc7a5\uc5d0\uc11c\ub294 \uc989\uc2dc \uc0ac\uc9c0 \ub9d0\uace0 \uae30\ub2e4\ub838\ub2e4\uac00 \ud22c\ub9e4\uac00 \uc77c\uc5b4\ub0a0 \ub54c\ub97c \uc7a1\uc544\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 8\n\n**\uc99d\uad8c\uc2dc\uc7a5 \ubd95\uad34 \ud6c4 \uc5b4\ub5a4 \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud560\uae4c**\n\n\uc5b4\ub290 \uc815\ub3c4 \uac00\uce58\ub97c \ubcf4\uc874\ud588\uac70\ub098 \ubcc4\ub85c \ub5a8\uc5b4\uc9c0\uc9c0 \uc54a\uc740 \uc8fc\uc2dd\uc740 \uc6b0\ub9ac\uac00 \ubaa8\ub974\ub294 \uc5b4\ub5a4 \uc774\uc720\uac00 \uc788\ub294 \uac83\uc774\ub2e4. **\uc644\uc804\ud788 \ud3ed\ub77d\ud55c \uc8fc\uc2dd\uc740 \uac70\uc758 \ud30c\uc0b0 \uc0c1\ud0dc\uc600\uc744 \uac83\uc774\ub2e4. \uc774\ub7f0 \uc8fc\uc2dd\uc740 \uc704\ud5d8\ud558\uc9c0\ub9cc, \uc804\ud658\uc810\uacfc \ud568\uaed8 \ud30c\uc0b0\uc744 \uba74\ud558\uac8c \ub418\uba74 \uac00\uaca9\uc774 \ub9ce\uc774 \uc624\ub97c \uac00\ub2a5\uc131\uc774 \uc788\ub2e4.** \ub530\ub77c\uc11c \ub098\ub294 \uc548\uc815\uc801\uc778 \uc8fc\uc2dd\uacfc \uc774\ub7f0 \uc8fc\uc2dd\uc744 \uc11e\uc5b4\uc11c \uc0ac\uaca0\ub2e4.\n\n\ubaa8\ub4e0 \uc704\uae30 \ud6c4\uc5d0\ub294 \ub192\uc740 \uae08\ub9ac \ub54c\ubb38\uc5d0 \uc77c\uc2dc\uc801\uc778 \uc5b4\ub824\uc6c0\uc774 \uc0dd\uae30\uace0, \uc774\ub7ec\ud55c \uc77c\uc2dc\uc801 \uc5b4\ub824\uc6c0 \ub54c\ubb38\uc5d0 \ud3ed\ub77d\ud55c \uc8fc\uc2dd\uc774 \ub9ce\uc774 \uc0dd\uae34\ub2e4. \uc774\ub7f0 \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uac83\uc740 \uc635\uc158\uc744 \uc0ac\ub294 \uac83\uacfc \ube44\uc2b7\ud558\ub2e4. \ucd94\uc138\uac00 \ubc14\ub00c\uba74 2\ubc30 \ud639\uc740 3\ubc30 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc0b0 \uc9c1\uc804\uc5d0 \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uac83\uc740 \ud070 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\ub2e4\ub294 \uc7a5\uc810\uc774 \uc788\uc9c0\ub9cc, **\uc624\ub798 \uae30\ub2e4\ub824\uc57c \ud558\uace0 \uadf8 \uae30\ub2e4\ub9bc\uc774 \uace0\ud1b5\uc2a4\ub7ec\uc6b8 \uc218 \uc788\ub2e4.** \ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \ub3c8\uc740 \uace0\ud1b5\uc758 \uacb0\uacfc\ub77c\uace0 \ub9d0\ud558\uae30\ub3c4 \ud588\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 9\n\n**\uc99d\uad8c\uc2dc\uc7a5\uc758 \uac8c\uc784 \uc2dc\uc2a4\ud15c \uc804\ubc18\uc5d0 \ub300\ud574 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uac00**\n\n**\uc694\uc57d\ud574\uc11c \ub9d0\ud558\uba74, \ud56d\uc0c1 \uc8fc\uc758\ud558\uace0 \ubaa8\ub4e0 \uc608\uc5b8\uc744 \ubbff\uc9c0 \ub9d0\ub77c\ub294 \uac83\uc774\ub2e4.** \uc720\uac10\uc2a4\ub7fd\uac8c\ub3c4 \ub300\uc911\uc740 \uc774 \uc0ac\uc2e4\uc744 \ube68\ub9ac \uc78a\uc5b4\ubc84\ub9b0\ub2e4. \uad11\uace0\uac00 \ub728\uac70\uc6b0\uba74 \ub728\uac70\uc6b8\uc218\ub85d \ub300\uc911\uc740 \uac78\ub824\ub4e0\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 10\n\n**\ud22c\uc790\uc790\uac00 \uc9c0\uc801\uc73c\ub85c \ud589\ub3d9\ud55c\ub2e4\ub294 \uac83\uc758 \uc758\ubbf8**\n\n\uc9c0\uc801\uc73c\ub85c \ud589\ub3d9\ud55c\ub2e4\ub294 \uac83\uc740 \uc0dd\uac01\uc744 \ud55c\ub2e4\ub294 \uac83\uc774\uace0, \uac10\uc815\uc801\uc774\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc774\ub2e4. **\ud22c\uc790\uc790\ub294 \ubb34\uc5c7\uc774 \uc633\uace0 \uadf8\ub978\uc9c0\uc5d0 \ub300\ud574 \uc790\uc2e0\uc758 \uc0dd\uac01, \uc790\uc2e0\uc758 \uc544\uc774\ub514\uc5b4\uc640 \ubc29\ud5a5\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4\uc57c \ud558\uba70, \ub300\uc911\uc5d0\uac8c \ud729\uc4f8\ub824 \uac10\uc815\uc801\uc73c\ub85c \ud589\ub3d9\ud558\uc9c0 \uc54a\uc544\uc57c \ud55c\ub2e4.** \uc774\ub4e4\uc740 \ub300\ubd80\ubd84 \uc911\uc7a5\uae30\uc801\uc73c\ub85c \ubcf4\uba70 \ub17c\ub9ac\ub97c \uac00\uc9c0\uace0 \ud589\ub3d9\ud55c\ub2e4. \ud2c0\ub9b4 \uc218\ub294 \uc788\uc9c0\ub9cc, \ub17c\ub9ac\uac00 \uc544\uc8fc \uc5c6\ub294 \uac83\uacfc\ub294 \uc644\uc804\ud788 \ub2e4\ub974\ub2e4. \ud2c0\ub824\ub3c4 \uc5ec\ub7ec\ubd84\ub4e4\uc758 \ub17c\ub9ac\ub77c\uace0 \ud55c\ub2e4\uba74, \uadf8\uac83\uc740 \uc8fc\uc2dd\ud22c\uc790\uc758 \uc62c\ubc14\ub978 \uae38\uc774\ub77c\uace0 \ud560 \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 11\n\n**\ub300\uc911\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud558\ub294 \ub2a5\ub825**\n\n\ud22c\uc790 \uc911\uc5d0\ub3c4 \uadf8\ub7f4 \uc218 \uc788\ub294 \ub2a5\ub825\uc774 \uc788\ub294 \uc0ac\ub78c\uc740 \uadf9\ud788 \uc18c\uc218\uc774\ub2e4. **\ucd5c\ub300\ud55c \uc7a1\uc544\ub3c4 \uc2dc\uc7a5 \ucc38\uc5ec\uc790\ub4e4 \uc911 10%\ub9cc\uc774 \uadf8\ub7f0 \ub2a5\ub825\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4.** \ub300\uc911\uc758 \uc9c0\ubc30\uc801\uc778 \uc758\uacac\uc5d0 \ub3d9\uc758\ud558\uc9c0 \uc54a\uace0 \uc790\uc2e0\uc758 \uae38\uc744 \uac04\ub2e4\ub294 \uac83\uc740 \uc815\ub9d0 \uc5b4\ub824\uc6b4 \uc77c\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 12\n\n**\uc790\uc2e0\uc740 \uadf8\ub807\uac8c \ud560 \uc218 \uc788\ub098**\n\n\uadf8\ub807\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub807\uac8c \ub418\uae30\uae4c\uc9c0 \uc27d\uc9c0 \uc54a\uc558\ub2e4. **\uc218\ub144\uac04\uc758 \uacbd\ud5d8 \ud6c4\uc5d0\uc57c \ube44\ub85c\uc18c \ub098 \uc790\uc2e0\uc758 \uc774\ub860\uacfc \uc6d0\uce59\uc744 \uac00\uc9c0\uac8c \ub418\uc5c8\ub2e4.** \ud558\uc9c0\ub9cc \uc774\ub860\uacfc \uc6d0\uce59\uc744 \uc2e4\ucc9c\uc5d0 \uc62e\uae30\ub294 \uac83\uc740 \ub354\uc6b1 \uc5b4\ub835\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 13\n\n**\uc774\ub860\uacfc \uc6d0\uce59\uc774 \uc788\ub294\ub370\ub3c4 \uc5b4\ub824\uc6b4 \uc774\uc720**\n\n\ub2e4\ub978 \uc0ac\ub78c\uc774 \ud30c\ub2c8\uae4c \ub098\ub294 \uc0ac\uc57c\uaca0\ub2e4\uace0 \uc0dd\uac01\ud560 \ub54c, \ub2e4\ub978 \uc0ac\ub78c\uc774 \uc0ac\ub2c8\uae4c \ub098\ub294 \ud314\uc544\uc57c\uaca0\ub2e4\uace0 \uc0dd\uac01\ud560 \ub54c, \ub300\uc911\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud574\uc57c \ud55c\ub2e4\ub294 \ub0b4 \uc774\ub860\uc774 \ub9de\uae30\ub294 \ud558\uc9c0\ub9cc \ud639\uc2dc \uc774\ubc88\uc5d0\ub294 \ub2e4\ub974\uc9c0 \uc54a\uc744\uae4c \ud558\uace0 \uc758\uc2ec\ud588\ub2e4.\n\n\ub098\uc911\uc5d0\uc11c\uc57c \uc774\ubc88\uc5d0\ub3c4 \uc5ed\uc2dc \ub2e4\ub974\uc9c0 \uc54a\uace0 \ub0b4 \uc774\ub860\uc5d0 \ub530\ub77c \uc608\uc0c1\ud55c \uac83\uc774 \uc633\ub2e4\ub294 \uac83\uc744 \uae68\ub2ec\uc558\ub2e4. **\uc624\ub7ab\ub3d9\uc548\uc758 \ud6c8\ub828\uacfc \ube44\uc2fc \uc218\uc5c5\ub8cc\ub97c \uce58\ub974\uace0 \ub098\uc11c\uc57c \ub300\uc911\uacfc \ubc18\ub300\ub85c \ud589\ub3d9\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\ub2e4.**\n\n> \uc694\ucee8\ub300 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc21c\uc751\ud558\ub294 \uc0ac\ub78c\uc774 \ub418\uc9c0 \ub9d0\uc544\uc57c \ud560 \ubfd0\ub9cc \uc544\ub2c8\ub77c, \ub098\uc544\uac00 \uc21c\uc751\uc5d0 \ubc18\ub300\ud558\ub294 \uc0ac\ub78c\uc774 \ub418\uc5b4\uc57c \ud55c\ub2e4. \uc65c\ub0d0\ud558\uba74 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc77c\ubc18\uc801\uc778 \uc758\uacac\uc774\ub780 \ub2e8\ub3c8 1\uc6d0\uc758 \uac00\uce58\ub3c4 \uc5c6\ub294 \uac83\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 14\n\n**\uc21c\uc751\ud558\uc9c0 \uc54a\ub294 \uc0ac\ub78c\uc740 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uac00**\n\n\uc758\uc2ec\uc744 \ud558\uace0, \ud68c\uc758\uc801\uc774 \ub418\uace0, \uc57d\uac04\uc758 \uacf5\uc0c1\ub3c4 \ud560 \uc904 \uc54c\uc544\uc57c \ud55c\ub2e4. **\uc790\uc2e0\uc758 \uc0dd\uac01\uc774 \ud655\uace0\ud55c \ud22c\uc790\uc790\ub294 \uc740\ud589, \uc5b8\ub860, \ud22c\uc790\uc0c1\ub2f4\uc0ac\ub294\ucee4\ub155 \uce5c\uc544\ubc84\uc9c0\uc758 \ub9d0\ub3c4 \ubb34\uc2dc\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4.**\n\n\ud2b9\ud788 \uc0c1\ub2f4\uc0ac\ub294 \uc8fc\uc758\ud574\uc57c \ud55c\ub2e4. \uc774\ub4e4\uc740 \uc8fc\uc2dd\uc2dc\uc7a5 \uc804\uccb4\ub97c \uc218\uc218\ub8cc\uc758 \uad00\uc810\uc73c\ub85c \ubc14\ub77c\ubcf8\ub2e4. \uc0c1\ub2f4\uc0ac\ub77c\uace0 \ud574\uc11c \ub2e4\ub978 \uc0ac\ub78c\ubcf4\ub2e4 \ub354 \ub9ce\uc774 \uc544\ub294 \uac83\uc740 \uc544\ub2c8\ub2e4. \uc774\ub4e4\uc740 \uac70\ub798\ub7c9\uc744 \ub298\ub9ac\uace0 \uc218\uc218\ub8cc\ub97c \ucc59\uae30\ub294 \uac83\ub9cc \uc0dd\uac01\ud55c\ub2e4.\n\n\ud55c \uac00\uc9c0 \uc608\ub97c \uaf2d \ub4e4\uace0 \uc2f6\ub2e4. X\ub77c\ub294 \ud070 \uc99d\uad8c\uc0ac\uac00 \uac00\uc7a5 \ud070 \uace0\uac1d, \uc989 \uba87\ubc31\ub9cc \ub2ec\ub7ec\ub97c \ud22c\uc790\ud558\ub294 \ud380\ub4dc\ub85c\ubd80\ud130 \uc804\ud654\ub97c \ubc1b\uc558\ub2e4. \uc774 \ud380\ub4dc\ub294 US \ucca0\uac15 \uc8fc\uc2dd\uc744 \ub300\ub7c9\uc73c\ub85c \ud314\uace0 \ub300\uc2e0 \ub300\ub7c9\uc758 \ubca8\ub818 \ucca0\uac15 \uc8fc\uc2dd\uc744 \uc0ac\uace0 \uc2f6\ub2e4\uace0 \uc758\ub8b0\ud588\ub2e4. \uc804\ud654\ub97c \ubc1b\uc740 \uc99d\uad8c\uc0ac\ub294 \ubc14\ub85c \uc218\ucc9c \uba85\uc758 \uace0\uac1d\ub4e4\uc5d0\uac8c \uc804\ubcf4\ub97c \ubcf4\ub0b4 US \ucca0\uac15\uc758 \uc8fc\uc2dd\uc744 \uc0ac\uace0 \ubca8\ub818 \uc8fc\uc2dd\uc744 \ud314\ub77c\uace0 \uad8c\uace0\ud588\ub2e4. \uc774\ub294 \ub300\ud615 \ud380\ub4dc\uac00 \uc758\ub8b0\ud55c \uac83\uacfc \uc815\ud655\ud788 \ubc18\ub300\ub418\ub294 \uac83\uc774\uc5c8\ub2e4. **\uc989 \ub2e4\uc218\uc758 \uc791\uc740 \uace0\uac1d\ub4e4\uc5d0\uac8c \ud53c\ud574\uac00 \uac00\ub354\ub77c\ub3c4 \ud070 \uace0\uac1d\uc5d0\uac8c \uc720\ub9ac\ud55c \uc815\uc138\ub97c \ub9cc\ub4e0 \ucabd\uc73c\ub85c \uac14\ub358 \uac83\uc774\ub2e4.** \uc724\ub9ac\uc801\uc778 \uba74\uc73c\ub85c \ubcf4\uc544 \uc0c1\ub2f4\uc0ac\ub4e4\uc758 \ud589\ub3d9\uc740 \ube44\ub09c\ubc1b\uc544 \ub9c8\ub545\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 15\n\n**\ud6cc\ub96d\ud55c \ud22c\uc790\uc790\uac00 \uac16\ucd94\uc5b4\uc57c \ud560 \uac83**\n\n**\uc608\ub9ac\ud568, \uc9c1\uad00, \uc0c1\uc0c1\ub825\uc774\ub2e4.**\n\n- \uc608\ub9ac\ud568\uc740 \uc0ac\uac74\uc758 \uc5f0\uad00 \uad00\uacc4\ub97c \uc774\ud574\ud558\uace0 \ub17c\ub9ac\uc801\uc778 \uac83\uacfc \ube44\ub17c\ub9ac\uc801\uc778 \uac83\uc744 \uad6c\ubcc4\ud560 \uc904 \uc544\ub294 \ub2a5\ub825\uc774\ub2e4.\n- \uc9c1\uad00\uc774\ub77c \ud568\uc740 \uc624\ub7ab\ub3d9\uc548\uc758 \uc8fc\uc2dd\ud22c\uc790\uc640 \uc0b6\uc758 \uacbd\ud5d8\uc5d0\uc11c \uc6b0\ub7ec\ub098\uc624\ub294 \ubb34\uc758\uc2dd\uc801\uc778 \ub17c\ub9ac\ub825\uc774\ub2e4.\n- \uc0c1\uc0c1\ub825\uc740 \uc88b\uc740 \uac83\uc774\ub4e0 \ub098\uc05c \uac83\uc774\ub4e0 \uc788\uc744 \uc218 \uc788\ub294 \ubaa8\ub4e0 \uac83\uc744 \uc0dd\uac01\ud574 \ubcf4\ub294 \ub2a5\ub825\uc774\ub2e4.\n\n\uc774\uc640 \ub354\ubd88\uc5b4 \uc808\uc81c\ub825\uc774 \uc788\uc5b4\uc57c \ud558\uace0, \uc790\uc2e0\uc774 \uc798\ubabb \uc0dd\uac01\ud588\ub2e4\ub294 \uac83\uc744 \uc778\uc815\ud560 \uc218 \uc788\ub294 \uc735\ud1b5\uc131\uc774 \uc788\uc5b4\uc57c \ud55c\ub2e4. \ub610\ud55c \ud6cc\ub96d\ud55c \ud22c\uc790\uc790\ub294 **\uc790\uc2e0\uc758 \uc0c1\uc0c1\uc774 \ud604\uc2e4\ub85c \ub420 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9b4 \uc218 \uc788\ub294 \uc778\ub0b4\uc2ec**\uc744 \uac00\uc9c0\uace0 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc131\uacf5\ud558\uac70\ub098 \uc2e4\ud328\ud560 \ub54c\ub9c8\ub2e4 \uc5b4\ub5a4 \uc0ac\uac74 \ub54c\ubb38\uc5d0 \uadf8\ub7f0 \uacb0\uacfc\uac00 \uc654\ub294\uc9c0 \uc2a4\uc2a4\ub85c \ud53c\ub4dc\ubc31\uc744 \ud574\uc57c \ud55c\ub2e4.\n\n> \uc8fc\uc2dd\uc73c\ub85c \ubc88 \ub3c8\uc740 \ub2e4\uc74c\uc5d0 \ub192\uc740 \uc774\uc790\uc640 \ud568\uaed8 \ub3cc\ub824\uc918\uc57c \ud558\ub294 \ube4c\ub9b0 \ub3c8\uc5d0 \ubd88\uacfc\ud558\ub2e4. \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uac70\ub300\ud55c \uace0\ub9ac\ub300\uae08\uc5c5\uc790\uc774\ub2e4.\n\n\uc131\uacf5\ud560 \ub54c\ub3c4 \"\uc774\uac70\ub294 \ub0b4\uac00 \uc6b4\uc774 \uc88b\uc544\uc11c \ub41c \uac83\uc774\ub2c8\uae4c \ub354 \uc5f4\uc2ec\ud788 \ub178\ub825\ud574\uc57c\uaca0\ub2e4\"\ub77c\uace0 \uc0dd\uac01\ud560 \uc218 \uc788\ub294 \uc0ac\ub78c\ub4e4\uc774 \uacb0\uad6d\uc5d0\ub294 \ub3c8\uc744 \ubc88\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 16\n\n**\ud22c\uc790\uc790\ub294 \uc5b4\ub5a4 \uc9c1\uc5c5\uc5d0 \uac00\uc7a5 \uac00\uae4c\uc6b8\uae4c**\n\n\uac00\uc7a5 \uac00\uae4c\uc6b4 \uac83\uc740 \uc758\uc0ac\uace0, \ubcc0\ud638\uc0ac, \ucde8\uc7ac \uae30\uc790\uc640 \ube44\uc2b7\ud55c \uc810\uc774 \uc788\ub2e4. **\uc5d4\uc9c0\ub2c8\uc5b4, \uacbd\uc81c\ud559\uc790, \uacbd\uc601\ud559\uc790\uc640\ub294 \ube44\uc2b7\ud55c \uc810\uc774 \uc5c6\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 17\n\n**\ud22c\uc790\uc790\uc640 \uc758\uc0ac\uc758 \uacf5\ud1b5\uc810**\n\n\ud22c\uc790\uc790\uc640 \uc758\uc0ac \ub458 \ub2e4 \uba3c\uc800 \uc9c4\ub2e8\uc744 \ud55c\ub2e4. \uadf8 \uc9c4\ub2e8\uc73c\ub85c\ubd80\ud130 \uce58\ub8cc \ubc29\ubc95\uc744 \ube44\ub86f\ud55c \ubaa8\ub4e0 \uac83\uc744 \ub04c\uc5b4\ub0b8\ub2e4. \uc758\uc0ac\uc640 \ub9c8\ucc2c\uac00\uc9c0\ub85c \ud22c\uc790\uc790\ub3c4 \uc790\uc2e0\uc758 \uacb0\uc815\uc774 \uc798\ubabb\ub41c \ubc29\ud5a5\uc73c\ub85c \uac00\uace0 \uc788\uc74c\uc744 \uc54c\uc544\ucc44\uba74 \ubc29\ubc95\uc744 \uace0\uce58\uace0 \uc0c8\ub85c\uc6b4 \ud574\uacb0\ucc45\uc744 \ucc3e\ub294\ub2e4. **\ud22c\uc790\uc790\uc5d0\uac8c\ub294 \uc9c1\uad00\uc774 \ud544\uc218 \ubd88\uac00\uacb0\ud55c \uac83\uc774\ub2e4. \ud22c\uc790\uc790\ub294 \uc0c1\uc0c1\uc744 \ud558\uace0, \uc5d4\uc9c0\ub2c8\uc5b4\ub294 \uacc4\uc0b0\uc744 \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 18\n\n**\ud22c\uc790\uc5d0 \ub098\uc05c \uc131\uaca9\uc774\ub780**\n\n\uc2e4\ud328\uc5d0\uc11c \ubc30\uc6c0\uc744 \ub04c\uc5b4\ub0b4\ub294 \uc735\ud1b5\uc131\uc774 \uc88b\uc740 \uc131\uaca9\uc778 \ubc18\uba74, **\uace0\uc9d1\uc2a4\ub7ec\uc6b4 \uac83\uc774 \uac00\uc7a5 \ub098\uc058\ub2e4.** \ubb3c\ub860 \ud655\uc2e0\uc740 \uac00\uc838\uc57c \ud558\uc9c0\ub9cc, \uc790\uc2e0\uc758 \uc798\ubabb\uc744 \ubc1c\uacac\ud588\ub2e4\uba74 \uace7\uc7a5 \uac70\uae30\uc11c \ub098\uc640\uc57c \ud55c\ub2e4. \uc798\ubabb\uc774\ub77c \ud568\uc740 \uacc4\uc0b0\ud55c \uc8fc\uc2dd\uc774 \uc190\uc2e4\uc774 \ub41c \uac83\uc774 \uc544\ub2c8\ub77c, \uc790\uc2e0\uc758 \ub17c\ub9ac\ub97c \ub9cc\ub4dc\ub294 \uacfc\uc815\uc5d0\uc11c \uc2e4\uc218\ub97c \ud588\uac70\ub098 \uc804\ud600 \ub73b\ud558\uc9c0 \uc54a\uc740 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub0ac\uc74c\uc744 \uae68\ub2eb\uac8c \ub41c \uac83\uc744 \ub9d0\ud55c\ub2e4.\n\n\uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \ud6cc\ub96d\ud55c \ud22c\uc790\uc790\ub294 \uc608\uce21\ud560 \uc218 \uc5c6\ub294 \uc77c\uc774 \uc77c\uc5b4\ub0a0 \uc218 \uc788\uc74c\uc744 \uacc4\uc0b0\uc5d0 \ub123\uc5b4\uc57c \ud55c\ub2e4. \uace0\uc9d1\uacfc \ud655\uc2e0\uc758 \ubbf8\ubb18\ud55c \ucc28\uc774\ub97c \uc774\ud574\ud558\uace0, \ud655\uc2e0\uc774 \uc798\ubabb\ub418\uc5c8\ub2e4\uba74 \uacfc\uac10\ud788 \ubc84\ub9b4 \uc218 \uc788\ub294 \uc6a9\uae30\uac00 \ud544\uc694\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 19\n\n**\uc8fc\uc2dd\ud22c\uc790\ub294 \uc5b4\ub5a4 \ub180\uc774\uc640 \uac00\uc7a5 \ube44\uc2b7\ud560\uae4c**\n\n\ud3ec\ucee4, \ube0c\ub9bf\uc9c0 \ub4f1 \uce74\ub4dc \ub180\uc774\uc640 \uac00\uc7a5 \ube44\uc2b7\ud558\ub2e4. \uce74\ub4dc \uac8c\uc784\uc744 \ud560 \ub54c \uc8fc\uc5b4\uc9c0\ub294 \uce74\ub4dc\uc5d0 \ub9de\uac8c \uac8c\uc784\uc744 \ud558\ub4ef\uc774, \ud22c\uc790\uc790\ub294 \ub04a\uc784\uc5c6\uc774 \ubcc0\ud654\ud558\ub294 \uc0c1\ud669\uc5d0 \uc801\uc751\ud574\uc57c \ud55c\ub2e4. **\uce74\ub4dc \uac8c\uc784\uc758 \ubca0\ud14c\ub791\uc774 \uc88b\uc740 \uce74\ub4dc\ub85c \ub9ce\uc774 \ubc8c\uace0 \ub098\uc05c \uce74\ub4dc\ub85c \uc870\uae08 \uc783\ub4ef\uc774, \ud6cc\ub96d\ud55c \ud22c\uc790\uc790\ub3c4 \uc790\uc2e0\uc5d0\uac8c \uc88b\uc740 \uc0ac\uac74\uc774 \uc0dd\uae30\uba74 \ub9ce\uc774 \ubc8c\uace0 \ub098\uc05c \uc0ac\uac74\uc774 \uc0dd\uae30\uba74 \uc801\uac8c \uc783\ub294\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 20\n\n**\ud22c\uc790\uc790\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uae4c**\n\n\ud22c\uc790\uc790\ub294 \ub04a\uc784\uc5c6\uc774 \ub4e3\uace0 \uc0ac\uc2e4\uc744 \uc0dd\uac01\ud574\uc57c \ud558\uba70, \ub420 \uc218 \uc788\uc73c\uba74 \uc62c\ubc14\ub978 \uacb0\ub860\uc744 \ub3c4\ucd9c\ud558\uace0\uc790 \ud558\ub294 \uc77c\uc885\uc758 \ucca0\ud559 \ud589\uc704\ub2e4.\n\n> \ub098\ub294 \"\ub420 \uc218 \uc788\uc73c\uba74\"\uc774\ub77c\uace0 \ub9d0\ud558\uc9c0, \"\ud655\uc2e4\ud788\"\ub77c\uace0 \ud558\uc9c0\ub294 \uc54a\ub294\ub2e4.\n\n**\uc62c\ubc14\ub978 \uacb0\ub860\uc744 \ub0b4\ub9ac\uc9c0 \ubabb\ud55c\ub2e4\uace0 \ud574\ub3c4 \uc2a4\uc2a4\ub85c\uc758 \uacb0\ub860\uc774\ub77c\uace0 \ud55c\ub2e4\uba74 \uadf8\uac83\uc740 \ud6cc\ub96d\ud55c \ud22c\uc790\uc790\uc758 \uae38\uc774\ub2e4.** \uacbd\uc601\ud559\uc790\ub294 \uae30\uc5c5\uc744 \ubd84\uc11d\ud558\ub294 \ub370, \uc989 \uc7ac\ubb34\uc81c\ud45c\ub97c \ubd84\uc11d\ud558\ub294 \ub370 \uc77c\uc815\ud55c \uc5ed\ud560\uc744 \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc7ac\ubb34\uc81c\ud45c\ub294 \ud2c0\ub9ac\uac70\ub098 \uc704\uc870\ub418\ub294 \uacbd\uc6b0\uac00 \ub9ce\uace0, \ucd5c\uc18c\ud55c \ubd84\uc2dd\ud68c\uacc4\ub294 \uae30\ubcf8\uc774\ub2e4. \ub610 \uc7ac\ubb34\uc81c\ud45c\uac00 \uc815\uc9c1\ud558\uace0 \ubc14\ub974\ub2e4\uace0 \ud574\ub3c4 \uc774\uac83\uc740 \uc774\ubbf8 \uacfc\uac70\uc758 \uc815\ubcf4\ub2e4.\n\n**\uc2dc\uc138\uac00 \uc62c\ub77c\uac00\uace0 \ub0b4\ub824\uac00\ub294 \uac83\uc740 \uc8fc\uc2dd\uc774 \uc88b\uac70\ub098 \ub098\uc058\uae30 \ub54c\ubb38\uc774 \uc544\ub2c8\ub77c, \uc5b4\ub5a4 \uac00\uc815 \ud558\uc5d0 \uc88b\uac70\ub098 \ub098\uc058\uac8c \ub420 \uac00\ub2a5\uc131\uc774 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.** \uc7ac\ubb34 \uc9c0\ud45c\uac00 \ub098\ube60\ub3c4 \uc88b\uc740 \ubc29\ud5a5\uc73c\ub85c \ubc1c\uc804\ud560 \uc218 \uc788\ub2e4\uace0 \uc0dd\uac01\ub418\uba74 \uadf8 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 21\n\n**\uc2dc\uc7a5\uc774 \uacfc\ub9e4\uc218\u00b7\uacfc\ub9e4\ub3c4 \uc0c1\ud0dc\uc778\uc9c0 \uc5b4\ub5bb\uac8c \uc54c \uc218 \uc788\ub098**\n\n\uc9c0\ub09c \uba87 \ub2ec \ud639\uc740 \uba87 \ub144\uac04 \uac70\ub798\ub7c9\uc774 \uc5b4\ub5bb\uac8c \uc804\uac1c\ub418\uc5c8\ub294\uc9c0\ub97c \uc0b4\ud3b4\ubcf8\ub2e4. **\uba87 \ub2ec \uc804\ubd80\ud130 \uc8fc\uac00\uac00 \uc62c\ub77c\uac00\uace0 \uac70\ub798\ub7c9\uc774 \uacc4\uc18d \uc99d\uac00\ud55c\ub2e4\uba74, \ub9ce\uc740 \uc8fc\uc2dd\uc774 \uc18c\uc2e0\ud30c\uc758 \uc190\uc5d0\uc11c \ubd80\ud654\ub1cc\ub3d9\ud30c\uc758 \uc190\uc73c\ub85c \uc62e\uaca8 \uac14\uc74c\uc744 \ucd94\ub860\ud574 \ubcfc \uc218 \uc788\ub2e4.** \uac70\ub798\ub7c9\uc774 \ub9ce\uc73c\uba74 \ub9ce\uc744\uc218\ub85d \ub354\uc6b1 \uadf8\ub807\ub2e4.\n\n\uc8fc\uac00\uac00 \uc62c\ub77c\uac08 \ub54c \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uc0ac\ub78c\uc740 \ubd80\ud654\ub1cc\ub3d9\ud30c\ubfd0\uc774\ub2e4. \uc774\ub54c \uc18c\uc2e0\ud30c\ub294 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc84c\uc744 \ub54c \uc0c0\ub358 \uc8fc\uc2dd\uc744 \ub0b4\ub2e4 \ud310\ub2e4. \uc774\ub7f0 \uc6c0\uc9c1\uc784\uc740 \uc77c\uc815 \uae30\uac04 \uacc4\uc18d\ub41c\ub2e4. \uc18c\uc2e0\ud30c\ub294 \ud604\uae08\uc744 \uc950\uace0 \uc788\uc73c\uba74\uc11c \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \uc8fc\uc2dd\uc744 \ud314 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9b0\ub2e4. \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc8fc\uc2dd\uc744 \ub192\uc740 \uac00\uaca9\uc5d0 \ud314\uace0 \uc2f6\uc9c0\ub9cc \uc5ec\uc758\uce58 \uc54a\uc744 \ub54c\ub294 \ub354 \ub0ae\uc740 \uac00\uaca9\uc73c\ub85c \ud310\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 22\n\n**\ub300\uc911\uc774 \uacc4\uc18d \ub099\uad00\uc801\uc774\uba74 \uc5b4\ub5bb\uac8c \ub420\uae4c**\n\n\uc774 \uacbd\uc6b0\uc5d0\ub3c4 \uc8fc\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce58\ub294 \uc911\uc694\ud55c \uae30\uc220\uc801 \uc774\uc720\ub4e4\uc774 \uc788\ub2e4. \uc8fc\uac00\uac00 \uc870\uae08 \ub5a8\uc5b4\uc9c0\uba74 \uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0b0 \uc0ac\ub78c\uc740 \ub9c8\uc774\ub108\uc2a4\uac00 \ub41c\ub2e4. \uc740\ud589\uc740 \uacc4\uc88c \uc794\uace0\ub97c \ucc44\uc6b0\ub77c\uace0 \uc555\ub825\uc744 \uac00\ud55c\ub2e4. \ub9ce\uc740 \uc0ac\ub78c\ub4e4\uc774 \uc0c8\ub85c\uc6b4 \ub3c8\uc744 \uc9d1\uc5b4 \ub123\uac70\ub098 \uc8fc\uc2dd\uc744 \ud314\uc544\uc57c \ud55c\ub2e4. \uc8fc\uc2dd\uc744 \ud314\uba74 \uc8fc\uac00\ub294 \ub610 \ub5a8\uc5b4\uc9c0\uace0, \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\uba74 \ub610 \uc8fc\uc2dd\uc744 \ud30c\ub294 \uacfc\uc815\uc774 \ubc18\ubcf5\ub41c\ub2e4.\n\n\ub610\ud55c \uc911\uc559\uc740\ud589\uc774 \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uacfc\uc5f4\ub418\uc5c8\ub2e4\uace0 \ud310\ub2e8\ud558\uace0 \uae08\ub9ac\ub97c \uc62c\ub824\uc11c \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c8 \uc218\ub3c4 \uc788\ub2e4. **\ub300\uc911\uc758 \uc2ec\ub9ac\uc801 \ubc18\uc751\uc740 \uac00\uc7a5 \uc704\ud5d8\ud55c \uac83\uc774\ub2e4.**\n\n> \uc8fc\uac00\uac00 \ucd5c\uace0\uc810\uc5d0 \uc788\uc744 \ub54c \uc18c\uc2e0\ud30c\ub294 \ub3c8\uc744 \uac00\uc9c0\uace0 \uc788\uace0, \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \ud76c\ub9dd\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4.\n\n\uac70\ub798\ub7c9\uc774 \uc99d\uac00\ud558\ub294 \uac00\uc6b4\ub370 \uc8fc\uac00\uac00 \uacc4\uc18d \ub5a8\uc5b4\uc9c0\uba74 \uac70\ub798\ub7c9\uc740 \ub354\uc6b1 \ud33d\ucc3d\ud55c\ub2e4. \uc8fc\uc2dd\uc740 \uacc4\uc18d \ubd80\ud654\ub1cc\ub3d9\ud30c\uc758 \uc190\uc5d0\uc11c \uc18c\uc2e0\ud30c\uc758 \uc190\uc73c\ub85c \ub118\uc5b4\uac04\ub2e4. \uacb0\uad6d \ucd5c\uc545\uc758 \uc0c1\ud669\uc5d0\uc11c \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \ud22c\ub9e4\ud558\uace0 \uc190\uc744 \ud134\ub2e4. \uc8fc\uc2dd\uc740 \ub2e4\uc2dc \uc18c\uc2e0\ud30c\uc758 \uc190\uc5d0 \uc788\uac8c \ub41c\ub2e4. \ub098\uc911\uc5d0 \uc8fc\uac00\uac00 \uc624\ub974\uae30 \uc2dc\uc791\ud558\uba74 \uc18c\uc2e0\ud30c\uc758 \uc218\uc911\uc5d0 \uc788\ub358 \uc8fc\uc2dd\uc774 \ub2e4\uc2dc \ub098\uc624\uac8c \ub41c\ub2e4. \uadf8\ub7ec\uba74 \uc0c1\uc2b9 \uad6d\uba74\uc774 \ub2e4\uc2dc \uc2dc\uc791\ub418\ub294 \uac83\uc774\ub2e4.\n\n> \uc8fc\uac00\uac00 \ubc14\ub2e5\uc5d0 \uc788\uc744 \ub54c \uc18c\uc2e0\ud30c\ub294 \uc8fc\uc2dd\uc744 \uac00\uc9c0\uace0 \uc788\uace0, \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \ub3c8\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \uc8fc\uac00\uac00 \ucd5c\uace0\uc810\uc5d0 \uc788\uc744 \ub54c \uc18c\uc2e0\ud30c\ub294 \ub3c8\uc744 \uac00\uc9c0\uace0 \uc788\uace0, \ubd80\ud654\ub1cc\ub3d9\ud30c\ub294 \uc8fc\uc2dd\uc744 \uac00\uc9c0\uace0 \uc788\ub2e4. \ud604\uae08\uacfc \uc8fc\uc2dd \uc0ac\uc774\uc5d0 \uc774\ub7f0 \uc6c0\uc9c1\uc784\uc740 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \uc601\uc6d0\ud788 \uacc4\uc18d\ub41c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 23\n\n**\uac70\ub798\ub7c9\uacfc \uc8fc\uac00 \uc6c0\uc9c1\uc784\uc73c\ub85c \ubcf4\ub294 \uc2e0\ud638**\n\n| \uac70\ub798\ub7c9 | \uc8fc\uac00 | \uc2e0\ud638 |\n|---|---|---|\n| \uc801\ub2e4 | \ud558\ub77d | \ub098\uc05c \uc2e0\ud638 \u2014 \uc8fc\uac00\uac00 \uacc4\uc18d \ub5a8\uc5b4\uc9c0\ub824\ub294 \uc870\uc9d0 |\n| \ub9ce\ub2e4 | \ud558\ub77d | \uc88b\uc740 \uc2e0\ud638 \u2014 \uc8fc\uc2dd\uc774 \uc18c\uc2e0\ud30c\uc758 \uc190\uc73c\ub85c \ub4e4\uc5b4\uac00\ub294 \uc911 |\n| \ub9ce\ub2e4 | \uc0c1\uc2b9 | \ub098\uc05c \uc2e0\ud638 \u2014 \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uc911 |\n| \uc801\ub2e4 | \uc0c1\uc2b9 | \uc88b\uc740 \uc2e0\ud638 \u2014 \ub300\ub2e4\uc218 \uc8fc\uc2dd\uc774 \uc544\uc9c1 \uc18c\uc2e0\ud30c\uc758 \uc190\uc5d0 \uc788\ub294 \uc911 |\n\n**\ub300\ubd80\ubd84\uc758 \uc8fc\uc2dd \uc804\ubb38\uac00\u00b7\ubd84\uc11d\uac00\u00b7\ube0c\ub85c\ucee4\ub4e4\uc740 \uac70\ub798\ub7c9\uc774 \ub9ce\uc740 \uac00\uc6b4\ub370 \uac00\uaca9\uc774 \uc62c\ub77c\uac00\uba74 \uc88b\ub2e4\uace0 \ud55c\ub2e4.** \ud558\uc9c0\ub9cc \ucf54\uc2a4\ud1a8\ub77c\ub2c8\ub294 \uc774\uac83\uc774 \uc815\ub9d0 \uc88b\uc740 \uac83\uc774\ub0d0\uace0 \ubb3b\ub294\ub2e4. \ub300\ub2f5\uc740 \"\uc544\ub2c8\uc624\"\uc774\ub2e4. \uc624\ub298 \uc55e\uc744 \ub2e4\ud22c\uc5b4 \uc8fc\uc2dd\uc744 \uc0c0\ub358 \ubc14\ub85c \uadf8 \ub300\uc911\uc774 \ub098\uc911\uc5d0\ub294 \uc55e\uc744 \ub2e4\ud22c\uc5b4 \uc8fc\uc2dd\uc744 \ud310\ub2e4. **\uc7a5\uae30\uc801\uc73c\ub85c \ub300\uc911\uc758 \ud310\ub2e8\uc774 \uc633\uc558\ub358 \uc801\uc740 \uadf9\ud788 \ub4dc\ubb3c\ub2e4.**\n\n\uac70\ub798\ub7c9\uc774 \ub9ce\uc544\uc9c0\uba74 \ubcf8\uaca9\uc801\uc778 \uc6c0\uc9c1\uc784\uc774 \uc2dc\uc791\ub41c\ub2e4. \uc8fc\uac00\uac00 \uc62c\ub77c\uac00\ub294\ub370 \uac70\ub798\ub7c9\uc774 \ub9ce\uc544\uc9c0\uba74 \ubd90\uc774 \ucc3e\uc544\uc624\uace0, \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294\ub370 \uac70\ub798\ub7c9\uc774 \ub9ce\uc544\uc9c0\uba74 \ucc98\uc74c\uc5d0\ub294 \uc2dc\uc138\uac00 \ub5a8\uc5b4\uc9c0\ub2e4\uac00 \ub098\uc911\uc5d0\ub294 \uc644\uc804\ud55c \ud22c\ub9e4 \ud604\uc0c1\uc774 \uc77c\uc5b4\ub09c\ub2e4.\n\n**\uc624\ub298\uc758 \ub9e4\uc218\uc790\uac00 \uba70\uce60 \ud6c4\uc5d0 \ub9e4\ub3c4\uc790\uac00 \ub418\uae30 \ub54c\ubb38\uc5d0, \uc624\ub298 \ub9e4\uc218\uc790\ub97c \ubd84\uc11d\ud558\ub294 \uac83\uc774 \uc8fc\uc2dd\uc758 \uc9c8\uc744 \ubd84\uc11d\ud558\ub294 \uac83\ubcf4\ub2e4 \ub354 \uc911\uc694\ud558\ub2e4.** \uc8fc\uc2dd\uc774 \uc9c8 \ub098\uc05c \ubcf4\uc720\uc790\uc758 \uc190\uc5d0 \uc788\uc73c\uba74 \ucd5c\uace0\uc758 \uc8fc\uc2dd\ub3c4 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c8 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 24\n\n**\uc774\uac83\uc740 \uc77c\ubc18\uc801\uc778 \uc758\uacac\uc778\uac00**\n\n\uc544\ub2c8\ub2e4. \uc815\ubc18\ub300\ub2e4. \ub300\ubd80\ubd84\uc758 \uc0c1\ub2f4\uc0ac, \uc740\ud589, \uc5b8\ub860\uc740 \uac70\ub798\ub7c9\uc774 \ub9ce\uc740 \uac00\uc6b4\ub370 \uac00\uaca9\uc774 \uc62c\ub77c\uac00\uba74 \uc88b\ub2e4\uace0 \ud55c\ub2e4. \uadf8 \uc99d\uac70\ub85c \ub9ce\uc740 \ub300\uc911\uc774 \uc8fc\uc2dd\uc744 \uc0b0\ub2e4\ub294 \uac83\uc744 \ub304\ub2e4. **\ud558\uc9c0\ub9cc \uc624\ub298 \uc55e\uc744 \ub2e4\ud22c\uc5b4 \uc8fc\uc2dd\uc744 \uc0c0\ub358 \ubc14\ub85c \uadf8 \ub300\uc911\uc774 \ub098\uc911\uc5d0\ub294 \uc55e\uc744 \ub2e4\ud22c\uc5b4 \uc8fc\uc2dd\uc744 \ud310\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 25\n\n**\uacfc\ub9e4\uc218\u00b7\uacfc\ub9e4\ub3c4\uc758 \ub2e4\ub978 \uc9d5\ud6c4**\n\n\uc624\ub7ab\ub3d9\uc548 \uc0c1\uc2b9\uc774 \uacc4\uc18d\ub418\ub2e4\uac00 \uc815\uccb4\ub41c \ud6c4 \uc0c8\ub85c\uc6b4 \uad6c\ub9e4\uc790\ub97c \uae30\ub2e4\ub9ac\uace0, \uc88b\uc740 \ub274\uc2a4\uc5d0\ub3c4 \ub354 \uc774\uc0c1 \ubc18\uc751\ud558\uc9c0 \uc54a\uac70\ub098 \uc2ec\uc9c0\uc5b4 \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c4\ub2e4\uba74, **\uc774\ub294 \uc544\uc8fc \ub098\uc05c \uc2e0\ud638\uc774\ub2e4.** \uc2dc\uc7a5\uc774 \ud3ec\ud654 \uc0c1\ud0dc\uc5d0 \uc774\ub978 \uac83\uc774\ub2e4.\n\n\ubc18\ub300\ub85c \uc624\ub7ab\ub3d9\uc548 \ud558\ub77d\uc744 \ud558\ub2e4\uac00 \uc815\uccb4\ub41c \ud6c4 \ub098\uc05c \uc18c\uc2dd\uc5d0\ub3c4 \ub354 \uc774\uc0c1 \ub098\ube60\uc9c0\uc9c0 \uc54a\uac70\ub098 \uc2ec\uc9c0\uc5b4 \uc8fc\uac00\uac00 \uc624\ub978\ub2e4\uba74, **\uc774\ub294 \uc544\uc8fc \uc88b\uc740 \uc2e0\ud638\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 26\n\n**\uadf8\ub7f0 \uacbd\uc6b0 \ud22c\uc790\uc790\ub294 \uc5b4\ub5bb\uac8c \ud574\uc57c \ud558\ub294\uac00**\n\n**\uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc88b\uc740 \uc18c\uc2dd\uc5d0 \ub354 \uc774\uc0c1 \ubc18\uc751\ud558\uc9c0 \uc54a\uc73c\uba74 \uc2dc\uc7a5\uc5d0\uc11c \ub098\uc640\ub77c. \uadf8\ub9ac\uace0 \ub098\uc05c \uc18c\uc2dd\uc774 \uc544\ubb34 \uc601\ud5a5\ub3c4 \ub07c\uce58\uc9c0 \uc54a\ub294\ub2e4\uba74 \uc2dc\uc7a5\uc5d0 \ub4e4\uc5b4\uac00\ub77c.**\n\n\ub610, \uc678\uad6d\uc778\uc774 \ub9ce\uc774 \uc0b0\ub2e4\uba74 \uc99d\uad8c\uc2dc\uc7a5\uc774 \uc88b\ub2e4\uace0 \uc124\uba85\ud558\ub294 \uac83\ub3c4 \ub098\uc05c \uc2e0\ud638\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 27\n\n**\uc678\uad6d\uc778 \ud22c\uc790\uc790\uac00 \uc0ac\uba74 \uc88b\uc9c0 \uc54a\uc740\uac00**\n\n\uc678\uad6d\uc778\uc774 \uc0b4 \ub54c\ub294 \ubb3c\ub860 \uc88b\ub2e4. \uc8fc\uac00\uac00 \uc62c\ub77c\uac00\uae30 \ub54c\ubb38\uc774\ub2e4. \ud558\uc9c0\ub9cc \uadf8\ub4e4\uc774 \uc8fc\uc2dd\uc744 \ud314 \ub54c\ub294 \uadf8\ub9cc\ud07c \ubd88\ub9ac\ud558\ub2e4. **\uc774\ub4e4 \uc911\uc5d0\ub3c4 \ub611\uac19\uc774 \uc18c\uc2e0\ud30c\uc640 \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \uc788\ub2e4. \uc2ec\uc9c0\uc5b4 \ubd80\ud654\ub1cc\ub3d9\ud30c\uac00 \ub354 \ub9ce\uc744 \uc218\ub3c4 \uc788\ub2e4.** \uc678\uad6d \ud22c\uc790 \uae30\uae08\uc740 \uc870\uadf8\ub9cc \uae30\ud68c\ub97c \ubcf4\uace0 \uc2dc\uc7a5\uc5d0 \ub4e4\uc5b4\uc628\ub2e4. \ud558\uc9c0\ub9cc \uc704\ud5d8\uc774 \ubcf4\uc774\uac70\ub098 \uc774\ubbf8 \uc774\uc775\uc744 \ucc59\uae34 \ud6c4\uc5d0\ub294 \uadf8\ub9cc\ud07c \ube68\ub9ac \ub098\uac00 \ubc84\ub9b0\ub2e4. \ubaa8\ub450 \uac19\uc740 \uc2dc\uac04\uc5d0 \uc0ac\uace0 \uac19\uc740 \uc2dc\uac04\uc5d0 \ud314\uace0 \uc2f6\uc5b4 \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 28\n\n**\uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0ac\ub3c4 \ub420\uae4c**\n\n\uc790\uc2e0\uc774 \ub300\ucd9c\ubc1b\ub294 \uadf8 \uc561\uc218\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc7ac\uc0b0\uc744 \uac00\uc9c0\uace0 \uc788\ub294 \uc0ac\ub78c\ub9cc \uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0ac\ub3c4 \ub41c\ub2e4. **\ud558\uc9c0\ub9cc \ub098\ub294 \uc5b4\ub5a4 \uacbd\uc6b0\ub77c\ub3c4 \uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0ac\uc9c0 \ub9d0\ub77c\ub294 \uc785\uc7a5\uc774\ub2e4.**\n\n**\uacbd\ud5d8 1:** 1950\ub144\ub300 \uc911\ubc18 \ub274\uc695 \uc99d\uc2dc\ub294 \uc0c1\uc2b9 \ubb34\ub4dc\ub97c \ud0c0\uace0 \uc788\uc5c8\ub2e4. \ub098\ub294 \uac00\uc9c4 \ub9c8\uc9c0\ub9c9 \ub2ec\ub7ec\uae4c\uc9c0 \ud138\uc5b4\uc11c \uc804\uc790\uc0b0\uc5c5 \uc8fc\uc2dd\uc744 \uc0c0\ub2e4. \ubaa8\ub4e0 \ub3c8\uc744 \ub2e4 \ud22c\uc790\ud55c \ud6c4 \ub300\ucd9c \ud55c\ub3c4\uae4c\uc9c0 \ub300\ucd9c\uc744 \ubc1b\uc558\ub2e4. \ub2f9\uc2dc \ubbf8\uad6d \ub300\ud1b5\ub839\uc774\uc5c8\ub358 \uc544\uc774\uc820\ud558\uc6cc \uc7ac\uc120 \uc2b9\ub9ac\ub97c \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c \uba3c\uc800 \ub204\ub9ac\ub824\uace0 \ud588\ub2e4. \uadf8\ub7f0\ub370 1955\ub144 \uc544\uc774\uc820\ud558\uc6cc \ub300\ud1b5\ub839\uc774 \uc2ec\uc7a5 \ubc1c\uc791\uc744 \uc77c\uc73c\ucf30\ub2e4. \ub2e4\uc74c\ub0a0 \ub274\uc695 \uc99d\uc2dc\uc5d0\uc11c \ubaa8\ub4e0 \uc8fc\uc2dd\uc774 10%\uc5d0\uc11c 20%\uae4c\uc9c0 \uae09\ub77d\ud588\ub2e4. **\ub098\ub294 \uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0c0\uae30 \ub54c\ubb38\uc5d0 \ubd80\ub7b4\ubd80\ub7b4 \uc8fc\uc2dd\uc744 \ud314\uc558\ub2e4.** \uba70\uce60 \ud6c4 \uc544\uc774\uc820\ud558\uc6cc\uc758 \uac74\uac15 \uc0c1\ud0dc\uac00 \ub098\uc544\uc9c0\uba74\uc11c \uc99d\uad8c\uc2dc\uc7a5\uc740 \ub2e4\uc2dc \uc548\uc815\uc744 \ub418\ucc3e\uc558\uace0, \uc8fc\uac00\ub294 \uc624\ub974\uae30 \uc2dc\uc791\ud558\ub354\ub2c8 \uadf8 \uc77c\uc774 \ud130\uc9c0\uae30 \uc804\ubcf4\ub2e4 \ub354 \ub192\uc544\uc84c\ub2e4. \uc5b4\ub5a4 \uc8fc\uc2dd\uc740 10\ubc30\ub098 \uc62c\ub790\ub2e4. \ud558\uc9c0\ub9cc \ub0b4\uac8c\ub294 \ub108\ubb34 \ub2a6\uc740 \uc77c\uc774\uc5c8\ub2e4.\n\n**\ubd88\ud655\uc2e4\uc131\uc740 \uc8fc\uac00 \ud558\ub77d\uc744 \ub9cc\ub4e4\uace0, \uadf8\uac83\uc740 \uae30\ud68c\uac00 \ub41c\ub2e4.** \ub300\uc911\uacfc \ubd80\ud654\ub1cc\ub3d9\ud30c \ud22c\uc790\uc790\ub294 \ub73b\ubc16\uc758 \uc0ac\uac74\uc5d0 \ubd80\ub52a\uce58\uba74 \ubb38\uc81c\ub97c \uc9c1\uc2dc\ud560 \uc5ec\uc720\ub97c \uac16\uc9c0 \ubabb\ud55c\ub2e4. \uc2e0\uc6a9\uc73c\ub85c \uc8fc\uc2dd\uc744 \uc0b0 \uacbd\uc6b0, \uae09\ub77d\ud558\uba74\uc11c \uacc4\uc18d \uc8fc\uac00\uac00 \ub5a8\uc5b4\uc9c0\ub294 \uc0ac\ud0dc\uac00 \uc0dd\uae38 \uc218 \uc788\uae30 \ub54c\ubb38\uc5d0 \uac00\ub2a5\ud55c \ud55c \ube68\ub9ac \uc8fc\uc2dd\uc744 \ud314\uace0 \uc2f6\uc5b4 \ud55c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 29\n\n**\uc2e0\uc6a9\uc73c\ub85c \uc99d\uad8c\uc744 \uc0c0\uc744 \ub54c \uc88b\uc740 \uacbd\ud5d8\uc774 \uc788\uc5c8\ub098**\n\n**\uacbd\ud5d8 2:** 2\ucc28 \uc138\uacc4\ub300\uc804\uc774 \ub05d\ub098\uace0 \ub3c5\uc77c \ucc44\uad8c\uc73c\ub85c \ud070 \ub3c8\uc744 \ubc88 \uc774\uc57c\uae30\uc774\ub2e4. \ub098\ub294 \uc804\uc7c1\uc774 \ub05d\ub09c \ud6c4 \ub3c5\uc77c \ucc44\uad8c\uc5d0 \ubaa8\ub4e0 \ub3c8\uc744 \ub2e4 \ud138\uc5b4 \ub123\uc5c8\ub2e4. \uadf8\ub9ac\uace0 \ub300\ucd9c\ub3c4 \ud55c\ub3c4\uae4c\uc9c0 \ubc1b\uc558\ub2e4. \uadf8 \ud22c\uc790\ub294 \ub3c5\uc77c\uc758 \ubbf8\ub798\ub97c \ubcf4\uace0 \ud55c \uac83\uc774\uc5c8\uace0 \uc544\ub370\ub098\uc6cc\uc758 \uac1c\uc778\uc801 \uc774\ubbf8\uc9c0\uc640\ub3c4 \uc5f0\uad00\ub418\uc5b4 \uc788\uc5c8\ub2e4.\n\n\ub098\ub294 \ub2f9\uc2dc \ubbf8\uad6d\uc5d0 \uac00 \uc788\uc5b4\uc57c \ud588\ub294\ub370, \ub3c5\uc77c \ucc44\uad8c \ub54c\ubb38\uc5d0 \ub9c8\uc74c\uc774 \ud3b8\uce58 \uc54a\uc558\ub2e4. \ub098\ub294 \uc740\ud589\uc5d0\uac8c \ub098\uc05c \ub274\uc2a4\uac00 \ub098\uc62c \uacbd\uc6b0 \ub0b4 \ub3c5\uc77c \ucc44\uad8c\uc744 \ubaa8\ub450 \ud314\uc544 \ub2ec\ub77c\uace0 \ubd80\ud0c1\ud558\ub824\uace0 \ud588\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub290 \uc740\ud589\ub3c4 \uc774 \uc758\ub8b0\ub97c \ubc1b\uc544\ub4e4\uc774\uc9c0 \uc54a\uc558\ub2e4. \ub450\ub824\uc6c0\uc5d0 \ub5a8\uba74\uc11c \ubbf8\uad6d\uc73c\ub85c \ub5a0\ub0ac\ub2e4. **\ub2e4\ud589\ud788\ub3c4 \ubbf8\uad6d\uc5d0 \uc788\ub294 \ub3d9\uc548 \ub098\uc05c \uc77c\uc774 \uc77c\uc5b4\ub098\uc9c0 \uc54a\uc558\ub2e4.** \ub450\ub824\uc6c0\uc744 \ub5a8\uce58\uc9c0 \ubabb\ud588\uc9c0\ub9cc \ub05d\uae4c\uc9c0 \uc0c1\uc2b9 \uc6c0\uc9c1\uc784\uc5d0 \ucc38\uc5ec\ud574 \uacb0\uad6d \uc774\uc775\uc744 \ubcfc \uc218 \uc788\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 30\n\n**\uadf8 \ud22c\uc790\uc758 \uacb0\uacfc\ub294 \uc5b4\ub5a0\ud588\ub294\uac00**\n\n\uc544\uc8fc \uc88b\uc558\ub2e4. **\ud558\uc9c0\ub9cc \uc544\ub370\ub098\uc6cc\uc758 \uac74\uac15\uc774 \uc544\ub2c8\ub77c\ub3c4 \ub2e4\ub978 \ub098\uc05c \uc18c\uc2dd\uc774 \uc788\uc5c8\ub2e4\uba74 \uc2e4\ud328\ud560 \uc218\ub3c4 \uc788\uc5c8\ub2e4.** \uadf8\ub7ac\ub2e4\uba74 \ub0b4 \uacc4\uc88c\ub3c4 \uce58\uba85\uc801\uc778 \ud0c0\uaca9\uc744 \uc785\uc5c8\uc744 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 31\n\n**\uc2e0\uc6a9 \uc5c6\uc774 \ud22c\uc790\ud588\ub2e4\uba74 \uc5b4\ub5bb\uac8c \ud588\uaca0\ub294\uac00**\n\n\ub54c\ub294 1962\ub144\uc774\uc5c8\ub2e4. \ub098\ub294 \ubaa8\uc740 \ub3c8\uc744 \ud138\uc5b4\uc11c \ud30c\ub9ac \uc99d\uad8c\uac70\ub798\uc18c\uc5d0\uc11c \ud504\ub791\uc2a4 \uc8fc\uc2dd\uc744 \uc0c0\ub2e4. **\uc774\ubc88\uc5d0\ub294 \ube5a\uc774 \uc804\ud600 \uc5c6\uc774 \ubaa8\ub450 \ub0b4 \ub3c8\uc73c\ub85c \uc0b0 \uac83\uc774\uc5c8\ub2e4.**\n\n\ub2f9\uc2dc \ud504\ub791\uc2a4\ub294 \uc54c\uc81c\ub9ac\uc5d0\uc11c \uc804\uc7c1\uc744 \uce58\ub974\uace0 \uc788\uc5c8\ub2e4. \ub098\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uac00\ub294 \ub300\uc2e0 \ub2e8\uace8 \uc2dd\ub2f9 \uc250 \ub8e8\uc774\uc5d0 \uac14\ub2e4. \uc2dc\uc7a5\uc5d0 \ub300\ud574 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \uba54\ub274\ud310\uc744 \uc5f4\uc2ec\ud788 \ub4e4\uc5ec\ub2e4\ubcf4\uc558\ub2e4. \ub204\uad70\uac00 \uc9c0\uae08 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uadf8\uc57c\ub9d0\ub85c \ud53c\ubc14\ub2e4\ub77c\uace0 \uc54c\ub824\uc8fc\uc5c8\ub2e4.\n\n> \"\uadf8\ub798?\"\n\n\ub098\ub294 \uc774\ub807\uac8c \ub300\ub2f5\ud558\uace0 \uc544\ubb34\ub807\uc9c0\ub3c4 \uc54a\uac8c \uc810\uc2ec \uc2dd\uc0ac\ub97c \uc990\uacbc\ub2e4. \ub0b4\uac8c \uc774\ubc88 \uc0ac\ud0dc\ub294 \uc2dc\uac04\uc774 \uc9c0\ub098\uba74 \uace7 \uc78a\ud600\uc9c0\ub294 \uadf8\ub0a0\uc758 \ub274\uc2a4\uc5d0 \ubd88\uacfc\ud588\ub2e4. \uadf8\ub54c \uc2dc\uc7a5\uc5d0 \uac14\ub354\ub77c\uba74 \ud2c0\ub9bc\uc5c6\uc774 \uc8fc\uc2dd\uc744 \ud314\uc558\uc744 \uac83\uc774\ub2e4. **\uadf8\ub7ec\ub098 \uc2dc\uc7a5\uc5d0 \uac00\uc9c0 \uc54a\uc558\ub358 \uac83\uc740 \ub0b4\uac00 \ube5a\uc774 \ud55c \ud47c\ub3c4 \uc5c6\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uac00\ub2a5\ud588\ub2e4.**\n\n\uc99d\uad8c\uc2dc\uc7a5\uc774 \ubb38\uc744 \ub2eb\uace0 1\uc2dc\uac04 \ud6c4, \uc7a5 \ub9c9\ud310\uc5d0 \uc2dc\uc7a5\uc774 \ub2e4\uc2dc \ub3cc\uc544\uc11c\uc11c \ud3ed\ub77d\ud588\ub358 \uc8fc\uac00\uc758 \ubc18\uc774 \ud68c\ubcf5\ub418\uc5c8\ub2e4\ub294 \uc18c\uc2dd\uc744 \ub4e4\uc5c8\ub2e4. \uc54c\uc81c\ub9ac \uc804\uc7c1\uc5d0 \ub300\ud55c \ub099\uad00\uc801\uc778 \ub274\uc2a4\uac00 \ub098\uc654\ub358 \uac83\uc774\ub2e4.\n\n> \ube5a\uc774 \uc5c6\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uadf8 \uc0c1\ud669\uc5d0\uc11c \uce68\ucc29\ud558\uac8c \ub300\uc751\ud560 \uc218 \uc788\uc5c8\ub2e4. \ube5a\uc774 \uc788\uc5c8\ub354\ub77c\uba74 \ub0b4 \ubaa8\ub4e0 \ub17c\ub9ac\ub3c4 \uc18c\uc6a9\uc5c6\uc5c8\uc744 \uac83\uc774\ub2e4.\n\n**\ub530\ub77c\uc11c \ub0b4 \uacb0\ub860\uc740 \uc774\ub807\ub2e4. \ube5a\uc774 \ub9ce\uc740 \ud68c\uc0ac\uc758 \uc8fc\uc2dd\uc744 \ub300\ub7c9\uc73c\ub85c \ub0a8\uc758 \ub3c8\uc73c\ub85c \uc0ac\ub294 \uac83\ubcf4\ub2e4, \uc791\uc9c0\ub9cc \ub0b4 \ub3c8\uc73c\ub85c \uc0b0 \uc8fc\uc2dd\uc744 \uac16\uace0 \uc788\uc73c\uba74 \uc8fc\uac00\uac00 \ubcf8\uaca9\uc801\uc73c\ub85c \uc62c\ub77c\uac08 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9b4 \uc218 \uc788\ub2e4.**\n\n\ud55c\ubc88\uc740 \ub0b4 \ub3d9\ub8cc \ud55c \uba85\uacfc \ub0b4\uac00 \ub611\uac19\uc740 \uc0dd\uac01\uc744 \ud558\uace0 \ub611\uac19\uc740 \uc99d\uad8c\uc744 \uc0c0\ub2e4. \ub098\ub294 \ubaa8\ub450 \ub0b4 \ub3c8\uc73c\ub85c \uc0c0\uace0 \uadf8\ub294 \uc2e0\uc6a9\uc73c\ub85c \uc0c0\ub2e4. \ub098\ub294 2\ub144\uac04 \uadf8 \uc99d\uad8c\uc744 \ubcf4\uc720\ud574 200%\uc758 \uc218\uc775\uc744 \ub0c8\ub2e4. \uadf8\ub7ec\ub098 \ub0b4 \ub3d9\ub8cc\ub294 \uc870\uae08\ub9cc \uc774\uc775\uc774 \ub098\ub3c4 \ube68\ub9ac \ud314\uc544 \uce58\uc6e0\ub2e4. \ube5a\uc744 \uc9c0\uace0 \uc788\uc5c8\uae30 \ub54c\ubb38\uc5d0 \uc870\uc2ec\uc2a4\ub7ec\uc6b8 \uc218\ubc16\uc5d0 \uc5c6\uc5c8\ub358 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 32\n\n**\uc704\ud5d8\uc744 \uac10\uc218\ud558\uc9c0 \uc54a\uace0\ub294 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \ub3c8\uc744 \ubc8c \uc218 \uc5c6\uc9c0 \uc54a\uc740\uac00**\n\n\ub9de\ub294 \ub9d0\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc99d\uad8c\uc2dc\uc7a5\uc758 \ucd94\uc138\ub97c \ubcf4\uace0 \ud22c\uc790\ud55c\ub2e4\uba74, \uc77c\ub958 \uae30\uc5c5\uc758 \uc8fc\uc2dd\uc744 \uc2e0\uc6a9\uc73c\ub85c \uc0ac\ub294 \uac83\ubcf4\ub2e4 \uacbd\uc81c\uac00 \uc88b\uc9c0 \uc54a\uc544\uc11c, \uae08\ub9ac\uac00 \ub192\uc544\uc11c \uc704\uae30\uc5d0 \ube60\uc9c4 \uae30\uc5c5\uc758 \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uac83\uc774 \uc88b\ub2e4. **\ubc18\ub4dc\uc2dc 100% \uc790\uae30 \ub3c8\uc73c\ub85c \uc0ac\uc57c \ud55c\ub2e4.** \ub450 \ubc88\uc9f8\ub294 \uc635\uc158\uc5d0 \ud22c\uc790\ud558\ub294 \uac83\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc774\ub54c \ud56d\uc0c1 \uc635\uc158\uc5d0 \ub123\ub294 \ub3c8 \uc804\uccb4\ub97c \ub0a0\ub9b4 \uc218 \uc788\ub2e4\ub294 \uac83\uc744 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. **\uc548\uc804\ud55c \uc8fc\uc2dd\uacfc \uc704\ud5d8\ud55c \uc8fc\uc2dd\uc744 \uc11e\uc5b4 \uc0ac\ub294 \uac83\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 33\n\n**\uc131\uacf5\uc801\uc778 \ud22c\uc790\ub97c \uc704\ud574 \ud558\ub8e8 \uc885\uc77c \ud544\uc694\ud55c\uac00**\n\n\uc544\ub2c8\ub2e4. \uacb0\uc815\uc5d0 \uc55e\uc11c \ucda9\ubd84\ud788 \ub530\uc838\ubcf4\uace0 \uc0dd\uac01\ud558\ub294 \uc2dc\uac04\uc744 \uaf2d \uac00\uc838\uc57c \ud55c\ub2e4. **\ub09a\uc2dc\ub294 \ud22c\uc790\uc790\uc5d0\uac8c \uc88b\uc740 \ucde8\ubbf8\ub2e4.** \ub09a\uc2ef\ub300\ub97c \ub4dc\ub9ac\uc6b0\uace0 \uc870\uc6a9\ud788 \uc549\uc544\uc11c \uc911\uc694\ud55c \ubb38\uc81c\uc5d0 \ub300\ud574 \uc0dd\uac01\ud560 \uc218 \uc788\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 34\n\n**\uc801\uc740 \ub3c8\uc73c\ub85c \ud070 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\ub294\uac00**\n\n\uc801\uc740 \ub3c8\uc73c\ub85c \ud070 \uc774\uc775\uc744 \ubcfc \uc218 \uc788\ub2e4. \uc644\uc804\ud788 \ubb34\ub108\uc84c\ub2e4\uac00 \uba87 \ub2ec \uc804\ubd80\ud130 \uc18c\uc0dd\ud558\ub294 \uc8fc\uc2dd, \uc989 \ud134\uc5b4\ub77c\uc6b4\ub4dc \uc8fc\uc2dd\uc744 \uc0ac\ub294 \uac83\uc774\ub2e4. \ub610 \ucd94\uc138\ub97c \uc815\ud655\ud788 \uc54c\uace0 \ud0c0\uc774\ubc0d\uc744 \ub9de\ucd94\uba74 \uc635\uc158\uc73c\ub85c\ub3c4 \ud070 \ub3c8\uc744 \ubc8c \uc218 \uc788\ub2e4.\n\n**\ubb3c\ub860 \uccab 100\ub9cc \ub2ec\ub7ec\ub97c \ub9cc\ub4e4\uae30\uac00 \uac00\uc7a5 \uc5b4\ub835\ub2e4.** \ud558\uc9c0\ub9cc \ub9ce\uc740 \uc80a\uc740 \ud22c\uc790\uc790\ub4e4\uc774 \uadf8\ub7f0 \uac83\ucc98\ub7fc \uc8fc\uc2dd\ud22c\uc790\ub85c \uc0dd\uacc4\ub97c \uc720\uc9c0\ud560 \uc218 \uc788\uc744 \uac83\uc774\ub77c\uace0\ub294 \uc0dd\uac01\ud558\uc9c0 \ub9d0\ub77c. \uc0dd\uacc4\ub294 \uc9c1\uc7a5\uc73c\ub85c \uafb8\ub9ac\uace0, \uc8fc\uc2dd\ud22c\uc790\ub85c\ub294 \ud070 \ub3c8\uc744 \ub9cc\ub4dc\ub294 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 35\n\n**\ud6cc\ub96d\ud55c \ud22c\uc790\uc790\ub77c\uba74 \uc5bc\ub9c8\ub97c \ubc8c \uc218 \uc788\ub294\uac00**\n\n**\uc8fc\uc2dd\ud22c\uc790\ub97c \ud1b5\ud574 \ub4e4\uc5b4\uc624\ub294 \ub3c8\uc740 \uc77c\uc744 \ud558\uace0 \ubc88 \uac83\uc774 \uc544\ub2c8\uae30 \ub54c\ubb38\uc5d0, \uc8fc\uc2dd\ud22c\uc790\ub85c\ub294 \uc6d4 \uc5bc\ub9c8\uc758 \uc18c\ub4dd\uc774 \uc788\ub2e4\uace0 \ub9d0\ud560 \uc218 \uc5c6\ub2e4.** \uc8fc\uc2dd\ud22c\uc790\ub97c \ud1b5\ud574 \uc774\uc775\uc744 \uc5bb\uc744 \uc218 \uc788\uace0 \ub54c\ub85c\ub294 \ud070 \uc774\uc775\uc73c\ub85c \ubd80\uc790\uac00 \ub420 \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \ub610 \uc190\uc2e4\uc744 \uc785\uc744 \uc218\ub3c4 \uc788\uace0 \ud070 \uc190\uc2e4\uc744 \uc785\uace0 \ud30c\uc0b0\ud560 \uc218\ub3c4 \uc788\ub2e4.\n\n\uc608\ub97c \ub4e4\uc5b4 \uc5b4\ub5a4 \ud22c\uc790\uc790\uac00 \uba87 \ub144\uac04 \uc544\ubb34 \uc131\uacfc \uc5c6\uc774 \uc190\uc2e4\uc744 \ubcf4\ub2e4\uac00 \ub2e8 6\uac1c\uc6d4 \ub3d9\uc548 \uc9c0\ub09c \uc218\ub144\uac04 \uc785\uc740 \uc190\uc2e4\ubcf4\ub2e4 \ub354 \ub9ce\uc740 \uc774\uc775\uc744 \ubcfc \uc218\ub3c4 \uc788\ub2e4. \uc694\ucee8\ub300 \uc99d\uad8c\uac70\ub798\uc5d0\uc11c\uc758 \uc131\uacf5\uc744 \uc6d4 \uc5bc\ub9c8, 1\ub144\uc5d0 \uba87 \ud37c\uc13c\ud2b8\uc758 \uc774\uc775\uc73c\ub85c \uc7b4 \uc218\ub294 \uc5c6\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 36\n\n**\ubaa8\ub4e0 \uc774\ub860\uc740 \ud68c\uc0c9\uc774\ub2e4**\n\n\uc808\ub300\uc801\uc73c\ub85c \ub9de\ub294 \ub9d0\uc774\ub2e4. **\uc8fc\uc2dd\ud22c\uc790\uc5d0 \ud559\ubb38\uc801 \uc774\ub860\uc774\ub098 \uc2dc\uc2a4\ud15c\uc774\ub77c\ub294 \uac83\uc740 \uc5c6\ub2e4.** \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ub2e8\uc9c0 \uc608\uac10\ubfd0, \uc544\ubb34\uac83\ub3c4 \uba85\ud655\ud788 \ubcfc \uc218 \uc5c6\ub2e4.\n\n> \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc5b8\uc81c \ud22c\uba85\ud588\ub358 \uc801\uc774 \uc788\ub358\uac00. \ud22c\uba85\ud558\uac8c \ubcfc \uc218 \uc788\ub2e4\uba74 \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc544\ub2d0 \uac83\uc774\ub2e4.\n\n**\ucd5c\uace0\uc758 \ud22c\uc790\uc790\ub3c4 \ubbf8\ub798\ub97c \ubcfc \uc218 \uc5c6\uace0, \uc548\uac1c \uc18d\uc758 \ud615\uccb4\ub9cc\uc744 \ud30c\uc545\ud560 \uc218 \uc788\uc744 \ubfd0\uc774\ub2e4.** \ub0b4\uc77c\uc774\ub098 \ubaa8\ub808\uac00 \uc5b4\ub5a8\uc9c0 \uc608\uce21\ud560 \uc218 \uc5c6\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 37\n\n**\ub3c8\uc774 \ud22c\uc790\uc790\uc758 \ud589\ub3d9\uc744 \uacb0\uc815\ud558\ub294 \ubaa8\ub4e0 \uac83\uc778\uac00**\n\n\uacbd\uc6b0\uc5d0 \ub530\ub77c\uc11c\ub294 \ud655\uc2e4\ud788 \ub3c8\uc774 \uc81c\uc77c \uc694\uc18c\uac00 \uc544\ub2c8\ub2e4. **\ud22c\uc790\ub294 \uc77c\uc885\uc758 \uc9c8\uc801\uc778 \uc2a4\ud3ec\uce20\uc774\ub2e4.** \ub530\ub77c\uc11c \ub2e8\uc21c\ud788 \ub3c8\uc744 \ubc8c\uc5b4\uc11c \uae30\uc058\uae30\ubcf4\ub2e4\ub294, \uc790\uae30 \uc0dd\uac01\uc774 \uc633\uc558\ub2e4\ub294 \uac83\uc774 \uc785\uc99d\ub410\ub2e4\ub294 \uac83\uc5d0 \ub354 \ud070 \uae30\uc068\uc744 \ub290\ub080\ub2e4. \ud22c\uc790\ub294 \uce74\uc9c0\ub178, \ub8f0\ub81b \uac8c\uc784, \uacbd\ub9c8 \ub4f1\uacfc \ub9c8\ucc2c\uac00\uc9c0\ub85c \uc2e0\uacbd\uc804\uc774\uba70, \uc5ec\uae30\uc11c \uc81c\uc77c \uc694\uc18c\ub294 \ub3c8\uc774 \uc544\ub2c8\ub77c \uc2b9\ub9ac\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 38\n\n**\ub300\uaddc\ubaa8 \ud22c\uc790\uc790\ub294 \uc704\ud5d8\ud55c \uc874\uc7ac\uc778\uac00**\n\n\uc5ec\uae30\uc5d0\ub294 \uc5b4\ub5a4 \uaddc\uce59\ub3c4 \uc5c6\ub2e4. \uc5b4\ub5a4 \uc9d1\ub2e8\uc774 \uc8fc\uc2dd\uc744 \uc0ac\ub4e4\uc5ec \uc5b4\ub290 \uae30\uc5c5\uc758 \uacbd\uc601\uad8c\uc744 \ucc28\uc9c0\ud558\ub824\uace0 \uacc4\ud68d\ud55c\ub2e4\uac00 \ucda9\ubd84\ud55c \uc218\uc758 \uc8fc\uc2dd\uc744 \uc0ac\uc9c0 \ubabb\ud558\uba74 \uc774\ubbf8 \uc0b0 \uc8fc\uc2dd\uc744 \ub2e4\uc2dc \ub0b4\ub2e4 \ud310\ub2e4. \uadf8\ub7ec\uba74 \ubc29\uae08 \uc804\uae4c\uc9c0 \uae09\ub4f1\ud558\ub358 \uc8fc\uc2dd\uc758 \uc2dc\uc138\ub294 \uc218\uc9c1\uc73c\ub85c \uae09\ub77d\ud55c\ub2e4. **\uc544\ubb34\uac83\ub3c4 \ubaa8\ub974\ub294 \uc0ac\ub78c\uc740 \uc65c \uc774\ub7f0 \uae09\ub4f1\uacfc \uae09\ub77d\uc774 \uc0dd\uae30\ub294\uc9c0 \uc774\ud574\uac00 \ub418\uc9c0 \uc54a\ub294\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 39\n\n**\uc774\uc775 \ud639\uc740 \uc190\uc2e4\uc774 \ud074 \ub54c \ud314\uc544\uc57c \ud560\uae4c**\n\n**\uc5b4\ub5a4 \uc99d\uad8c\uc744 \ud314 \uac83\uc778\uac00 \ub9d0 \uac83\uc778\uac00\ub97c \uacb0\uc815\ud558\ub294 \uac83\uc740 \uacfc\uac70\uc758 \ud310\ub9e4\uac00\uc640 \uc544\ubb34 \uad00\ub828\uc774 \uc5c6\uace0, \uc624\ub85c\uc9c0 \ubbf8\ub798\uc758 \uc804\ub9dd\uc5d0 \ub300\ud574 \uc5b4\ub5bb\uac8c \ud310\ub2e8\ud558\ub294\uac00\uc5d0 \ub2ec\ub824 \uc788\ub2e4.** \ud22c\uc790\uc790\ub294 \uc808\ub300\uc801\uc73c\ub85c \ub0c9\uc815\ud55c \ud310\ub2e8\uc744 \ub0b4\ub824\uc57c \ud55c\ub2e4. \uc190\uc2e4\uc744 \uc785\uc5c8\ub2e4 \ud558\ub354\ub77c\ub3c4 \uc790\uc2e0\uc758 \ud310\ub2e8\uc774 \ud314\ub77c\uace0 \ud558\uba74 \ud314\uc544\uc57c \ud55c\ub2e4.\n\n\uc190\uc2e4\uc744 \uc785\uc740 \ud22c\uc790\uc790 \ub300\ubd80\ubd84\uc774 \uc190\uc2e4\uc744 \uc785\uc5c8\ub2e4\ub294 \uc0ac\uc2e4\uc5d0 \uc9c1\uba74\ud558\uae30 \uc2eb\uc5b4\uc11c \uc8fc\uc2dd\uc744 \ud314\uc9c0 \ubabb\ud55c\ub2e4. **\uc774\ub7f0 \uc2ec\ub9ac\uc801 \ubc18\uc751\uc740 \uc644\uc804\ud788 \ud2c0\ub9b0 \uac83\uc774\ub2e4.** \ub0c9\uc815\ud55c \ud310\ub2e8\uc744 \ud558\uc9c0 \ubabb\ud558\uac8c \ub9cc\ub4e4\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 40\n\n**\uc2dc\uc138\ub97c \uc5b8\uc81c\ub098 \uad00\uc2ec \uc788\uac8c \ubd10\uc57c \ud558\ub098**\n\n\ub098\ub294 \uc5b8\uc81c\ub098 \uc815\ud655\ud55c \uc8fc\uac00\ub97c \ubaa8\ub978\ub2e4. \ub0b4\uac00 \uc0b0 \uc8fc\uc2dd\uc758 \uac00\uaca9\ub3c4 \ubaa8\ub978\ub2e4. \ud558\ub8e8\ud558\ub8e8\uc758 \ubcc0\ub3d9\uc5d0\ub294 \uc2e0\uacbd \uc4f0\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc774\ub2e4. **\ub098\ub294 \ub2e8\uc9c0 \uc885\ud569\uc9c0\uc218\uac00 \uc5bc\ub9c8\uc778\uc9c0 \uccb4\ud06c\ud558\ub294 \ub4f1 \ubd84\uc704\uae30\uac00 \uc5b4\ub5a4\uc9c0\ub9cc \uc0b4\ud540\ub2e4.** \ub098\ub294 \uc774\ubbf8 \ub0b4 \uc758\uacac\uc744 \uc815\ub9bd\ud574 \ub193\uace0 \uc778\ub0b4\ub97c \uac00\uc9c0\uace0 \ub0b4\uac00 \uc633\ub2e4\ub294 \uac83\uc774 \ub4dc\ub7ec\ub0a0 \ub54c\uae4c\uc9c0 \uae30\ub2e4\ub9b0\ub2e4. \ub54c\ub85c\ub294 \ub9de\uace0 \ub54c\ub85c\ub294 \ud2c0\ub9b4 \uc218\ub3c4 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\ub290 \uc815\ub3c4 \uc2dc\uac04\uc774 \uc9c0\ub09c \ud6c4 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \ub0b4\uac00 \uc633\ub2e4\ub294 \uac83\uc774 \uc544\uc9c1 \uc785\uc99d\ub418\uc9c0 \uc54a\uc558\uace0, \ub098 \ub610\ud55c \ub0b4 \uc758\uacac\uc744 \ubc14\uafb8\uc9c0 \uc54a\uc558\ub2e4\uba74 \ub098\ub294 \uce68\ucc29\ud568\uc744 \uc720\uc9c0\ud55c\ub2e4.\n\n\uc774\ub807\uac8c \ud558\uae30\uac00 \ub9e4\uc6b0 \uc5b4\ub835\ub2e4\ub294 \uac83\uc740 \uc54c\uace0 \uc788\ub2e4. \ub9ce\uc740 \ud6c8\ub828\uc774 \ud544\uc694\ud558\ub2e4. **\ud558\uc9c0\ub9cc \ud6c8\ub828\uc744 \ud558\uba74 \uc810\ucc28 \uadf8\ub7f0 \ud0dc\ub3c4\uc5d0 \uc775\uc219\ud558\uac8c \ub41c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 41\n\n**\uc131\uacf5\uc801\uc778 \ud22c\uc790 \ud6c4\uc5d0\ub294 \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uae4c**\n\n**\ud22c\uc790\ub85c \ubc88 \ub3c8\uc774 \uc544\uc8fc \ud070 \uae08\uc561\uc774\ub77c\ub3c4 \ud22c\uc790\uc790\ub294 \ud56d\uc0c1 \uacb8\uc190\ud574\uc57c \ud558\uba70 \uc2a4\uc2a4\ub85c \uc798\ud588\ub2e4\uace0 \uc0dd\uac01\ud574\uc120 \uc548 \ub41c\ub2e4.** \uc65c\ub0d0\ud558\uba74 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ubc14\ubcf4\ub4e4\ub3c4 \uc885\uc885 \uc131\uacf5\uc744 \ud558\uae30 \ub54c\ubb38\uc774\ub2e4. \uac00\ub2a5\uc131\uc740 \uc0c1\uc2b9\uacfc \ud558\ub77d \ub531 \ub450 \uac00\uc9c0\ubfd0\uc774\ub2e4. \ub450 \uac00\uc9c0 \uacbd\uc6b0 \uc911 \ud558\ub098\ub97c \ub9de\ud614\ub2e4\uace0 \uc2a4\uc2a4\ub85c \uc798\ub0ac\ub2e4\uace0 \uc0dd\uac01\ud560 \uc774\uc720\ub294 \ub418\uc9c0 \uc54a\ub294\ub2e4. \uc21c\uc804\ud788 \uc6b4\uc774 \uc88b\uc544\uc11c \uadf8\ub7ac\uc744 \uc218\ub3c4 \uc788\ub2e4.\n\n\uc0c8\ub85c\uc6b4 \uc544\uc774\ub514\uc5b4\uac00 \uc788\uc73c\uba74 \ud76c\ub9dd\uc744 \uac00\uc838\uc57c \ud55c\ub2e4. \ud558\uc9c0\ub9cc \uc57d\uac04\uc758 \ube44\ud310\uacfc \ube44\uad00\ub3c4 \ud56d\uc0c1 \ud544\uc694\ud558\ub2e4. \ub108\ubb34 \ub9ce\uc774 \uae30\ub300\ud558\uba74 \uc608\uce21\ud560 \uc218 \uc5c6\ub294 \uc77c\uc774 \ub07c\uc5b4\ub4e4\uc5b4 \uc77c\uc744 \ub9dd\uce5c\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 42\n\n**\ub3c5\ud559\ud55c \uc0ac\ub78c\uc758 \ub9d0\uc744 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uac00**\n\n\ud559\uad50\uc5d0\uc11c \ubc30\uc6b0\uc9c0 \uc54a\uc558\ub354\ub77c\ub3c4 \ub3c5\ud559\ud55c \uc0ac\ub78c\uc740 \ub9ce\uc740 \uacbd\ud5d8\uc744 \uac16\uace0 \uc788\uc73c\uba70, \uc885\uc885 \uc815\uc2dd\uc73c\ub85c \ubc30\uc6b4 \uc774\ub860\ubcf4\ub2e4 \uc5b4\ub5a4 \ubb38\uc81c\ub098 \uc0ac\uac74\uc5d0 \ubcf8\ub2a5\uc801\uc73c\ub85c \ub354 \uc798 \ub300\uc751\ud55c\ub2e4. **\ub3c5\ud559\uc73c\ub85c \uc775\ud78c \uc0ac\ub78c\uc740 \uc65c \uadf8\ub7f0\uc9c0\ub294 \uc798 \uc54c\uc9c0 \ubabb\ud558\uc9c0\ub9cc, \uacbd\ud5d8 \ub355\ubd84\uc5d0 \uc62c\ubc14\ub974\uac8c \ub300\uc751\ud55c\ub2e4.**\n\n40\ub300 \ud6c4\ubc18\uc758 \uc5f0\ub839\uce35\uc774\ub77c\uace0 \ud55c\ub2e4\uba74 \uc9c0\uae08 \ub2a6\uc5c8\ub2e4\uace0 \uc0dd\uac01\ud558\uc2e4 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub2e4. \uc5ec\ub7ec\ubd84\ub4e4\uc740 \ucda9\ubd84\ud788 \uc778\uc0dd\uc5d0\uc11c \uacbd\ud5d8\uc744 \uc313\uc558\uae30 \ub54c\ubb38\uc5d0 \uadf8\ub7f0 \uacbd\ud5d8\uc73c\ub85c \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub3c4 \uc5bc\ub9c8\ub4e0\uc9c0 \uc88b\uc740 \uc131\uacfc\ub97c \ub0bc \uc218 \uc788\ub2e4. \ucc45\uc744 \uc77d\uace0 \uc0dd\uac01\ud558\uace0 \uc2e4\ucc9c\ud558\uace0 \uc2e4\ud328\ud558\uace0 \uacbd\ud5d8\uc744 \uc313\ub294\ub2e4\uba74 \uac1c\uc778\ud22c\uc790\uc790\ub77c\ub3c4 \ud6cc\ub96d\ud55c \ud22c\uc790\uc790\uac00 \ub420 \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 43\n\n**\uc5b4\ub5a4 \uae30\uc900\uc5d0 \ub530\ub77c \uc8fc\uc2dd\uc744 \uc120\uc815\ud574\uc57c \ud558\ub294\uac00**\n\n\uccab \ubc88\uc9f8 \uacb0\uc815\ud574\uc57c \ud560 \uac83\uc740 \uc8fc\uc2dd\uc744 \uc0b4 \uac83\uc778\uac00, \uc544\ub2c8\uba74 \uc7a5\uae30 \ucc44\uad8c\uc5d0 \ub123\uc5b4 \ub458 \uac83\uc778\uac00\uc774\ub2e4. \uc8fc\uc2dd\uc744 \uc0ac\uae30\ub85c \uacb0\uc815\ud588\ub2e4\uba74 \uc5b4\ub5a4 \uc2dc\uc7a5\uc5d0\uc11c \ud560\uc9c0\ub97c \uacb0\uc815\ud55c\ub2e4. \uadf8\ub2e4\uc74c\uc740 \uc5b4\ub5a4 \uc0b0\uc5c5 \ubd84\uc57c\ub97c \uc0b4\uc9c0 \uacb0\uc815\ud55c\ub2e4. \uadf8\ub9ac\uace0 \ub9c8\uc9c0\ub9c9\uc73c\ub85c \uae30\uc5c5\uc744 \uace0\ub978\ub2e4. **\uc624\ub298 \uc0b4\uc9c0 \uc77c\uc8fc\uc77c \ud6c4\uc5d0 \uc0b4\uc9c0\ub294 \uc911\uc694\ud558\uc9c0 \uc54a\uc73c\uba70 \uc804\uc220\uc801\uc778 \uacb0\uc815\uc77c \ubfd0\uc774\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 44\n\n**\uc2e4\ud328\ud55c \ud22c\uc790\uc790\uc758 \uc758\uacac\uc740 \uc5bc\ub9c8\ub098 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud560\uae4c**\n\n**\uac00\uc7a5 \uc911\uc694\ud558\uac8c \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4.** \uc131\uacf5\uc774 \ud504\ub85c\uc758 \uc9c0\uc2dd\uc744 \uc7ac\ub294 \ucc99\ub3c4\uac00 \uc544\ub2c8\uae30 \ub54c\ubb38\uc774\ub2e4. \uc131\uacf5\ud558\uc9c0 \ubabb\ud55c \uc0ac\ub78c\ub3c4 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ucd94\uc138\uc640 \uae30\ud68c\ub97c \uc544\uc8fc \uc798 \ud310\ub2e8\ud560 \uc218 \uc788\uace0, \ud658\uc0c1\uc744 \ud3bc\uce58\uace0 \uc704\ud5d8\uc744 \uc7b4 \uc218 \uc788\ub2e4. **\uc131\uacf5\uc740 \ud55c \uc0ac\ub78c\uc758 \uc9c0\uc2dd\uc774 \uc544\ub2c8\ub77c \uc131\uaca9\uc5d0 \ub2ec\ub824\uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 45\n\n**\ud22c\uc790\uc790\ub294 \ubb34\uc5c7\uc744 \ud560 \uc904 \uc54c\uc544\uc57c \ud558\ub294\uac00**\n\n\ud22c\uc790\uc790\uc758 \uc5ed\ud560\uc740 \ud310\uc0ac\uc758 \uc5ed\ud560\uacfc \ube44\uc2b7\ud558\ub2e4. \ud310\uc0ac\ub294 \uc0ac\uac74\uc774 \uc77c\uc5b4\ub0ac\uc744 \ub54c \uadf8 \uc790\ub9ac\uc5d0 \uc788\uc9c0\ub3c4 \uc54a\uc558\uace0 \ucd1d\uae30 \uc804\ubb38\uac00\ub3c4 \uc544\ub2c8\ub2e4. \uadf8\ub7ec\ub098 \uadf8\ub294 \uc99d\uc778\uc744 \uc2ec\ubb38\ud558\uace0 \uc804\ubb38\uac00\ub4e4\uc758 \uc758\uacac\uc744 \ub4e4\uc740 \ud6c4 \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub0b4\ub9b0\ub2e4.\n\n\ud22c\uc790\uc790\ub294 \uc804\uc790, \ud56d\uacf5, \uc11d\uc720, \ucca0\ub3c4, \ucef4\ud4e8\ud130, \uc790\ub3d9\ucc28, \ud654\ud559 \ub4f1\uc758 \uc804\ubb38\uac00\uac00 \uc544\ub2c8\ub2e4. **\ud22c\uc790\uc790\ub294 \ub2e4\ub978 \uc0ac\ub78c\uc758 \uc870\uc0ac\uc640 \ubd84\uc11d\uc744 \ubc1b\uc544\ubcf4\uace0, \uad6d\uc81c\uc815\uce58\uc640 \uc911\uc559\uc740\ud589\uc758 \uae08\ub9ac \uc815\ucc45\uc744 \uc0b4\ud540 \ub2e4\uc74c \uc8fc\uc2dd\uc744 \uc0b4\uc9c0 \ub9d0\uc9c0 \uc790\uc2e0\uc758 \ud310\ub2e8\uc744 \ub0b4\ub9b0\ub2e4.**\n\n> \ubaa8\ub4e0 \uac83\uc744 \uc77d\uc744 \uc218\ub294 \uc5c6\ub2e4. \ud558\uc9c0\ub9cc \ubb34\uc5c7\uc774 \uc5b4\ub514\uc5d0 \uc788\ub294\uc9c0\ub294 \uc54c\uc544\uc57c \ud55c\ub2e4.\n\n**\ubaa8\ub4e0 \uac83\uc744 \uc870\uae08\uc529 \uc544\ub294 \uc0ac\ub78c\uc774 \uc99d\uc2dc\ub97c \ub354 \uc798 \uc774\ud574\ud55c\ub2e4.** \uc870\uae08\uc529 \ubc30\uc6b0\uace0 \ubcf4\uace0 \ub4e3\uace0 \uacbd\ud5d8\ud55c \ubaa8\ub4e0 \uac83\uc774 \ud22c\uc790\uc5d0 \ub3c4\uc6c0\uc774 \ub41c\ub2e4. \uac00\uc7a5 \uc911\uc694\ud55c \uac83\uc740 \uc0b6\uc744 \uc2a4\uc2a4\ub85c \uc5f0\uad6c\ud558\ub294 \uac83\uc774\ub2e4. \ub9ce\uc774 \uc5ec\ud589\ud558\uace0 \uc138\uacc4\uc640 \uadf8 \uc9c0\uc5ed\uc758 \uc0ac\ub78c\ub4e4\uc744 \ub9cc\ub098\ub77c. \uacbd\uc81c\uc804\ubb38\uac00, \uc740\ud589, \uc790\ubcf8 \uc911\uac1c\uc0ac, \uc815\uce58\uac00 \uac19\uc740 \uc885\uc871\uc744 \ubcfc \ub54c\ub294 \ud68c\uc758\uc801\uc778 \ub208\uc744 \uac00\uc838\ub77c.\n\n---\n\n## \ud3ec\uc778\ud2b8 46\n\n**\ube44\ubc95\uc5d0 \uad00\ud574 \uc5b4\ub5bb\uac8c \uc0dd\uac01\ud558\ub294\uac00**\n\n**\ube44\ubc95\uc5d0 \ub300\ud55c \ub0b4 \uc0dd\uac01\uc740 \uc544\uc8fc \ubd80\uc815\uc801\uc774\ub2e4. \uac00\uae4c\uc774 \ud558\uc9c0 \ub9d0\ub77c.** \ube44\ubc95\uc774\ub77c\uace0 \ud558\ub294 \uac83\uc758 90%\uac00 \uad11\uace0\ub098 \uc2ec\uc9c0\uc5b4 \uc870\uc791\uc774\ub2e4. \uc5b4\ub5a4 \uae08\uc735 \uadf8\ub8f9, \uae30\uad00 \ud639\uc740 \uc2e0\ub514\ucf00\uc774\ud2b8\uac00 \ub300\uc911\uc774 \ud2b9\uc815 \uc8fc\uc2dd\uc744 \uc0ac\uac8c \ud558\uae30 \uc704\ud574 \uc5b8\ub860\uacfc \uc785\uc18c\ubb38\uc744 \ud1b5\ud574 \ubd84\uc704\uae30\ub97c \ub744\uc6b4\ub2e4. \uc774\ubbf8 \ub9d0\ud588\ub4ef\uc774, \uacc4\uc18d \uc624\ub974\ub294 \uc8fc\uc2dd\uc744 \ub300\uc911\uc5d0\uac8c \ud30c\ub294 \uac83\ubcf4\ub2e4 \ub354 \uc26c\uc6b4 \uc77c\uc740 \uc5c6\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 47\n\n**\ub300\uaddc\ubaa8 \uc720\uba85 \uae30\uc5c5\uc774 \uc801\uadf9\uc801\uc73c\ub85c \ucd94\ucc9c\ud558\ub294 \uc885\ubaa9\uc744 \uc0ac\uc57c \ud560\uae4c**\n\n\uc544\ub2c8\ub2e4. **\ucd5c\ub300\ud55c \uc870\uc2ec\uc744 \ud558\ub77c.** \uae08\uc735\uae30\uad00\uc774 \uc8fc\uc2dd\uc744 \ud314\uace0 \uc2f6\uc73c\uba74 \uc740\ud589\uc774\ub098 \uc99d\uad8c \ud68c\uc0ac\ub97c \ud1b5\ud574 \uc798 \uc544\ub294 \uce7c\ub7fc\ub2c8\uc2a4\ud2b8\ub098 \uc99d\uad8c \uc18c\uc2dd\uc9c0\uc5d0 \ucd94\ucc9c \uc885\ubaa9\uc73c\ub85c \uc62c\ub9ac\ub3c4\ub85d \ud558\ub294 \uac83\uc774\ub2e4. \uc774\ub294 \uc77c\uc885\uc758 \ud504\ub85c\ubaa8\uc158\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 48\n\n**\ub300\uaddc\ubaa8 \uae30\uad00\uc758 \uba38\ub2c8\ub9e4\ub2c8\uc800\uac00 \ud589\ud558\ub294 \uc8fc\uc2dd \ub9e4\ub9e4 \ud589\uc704\ub97c \uc5bc\ub9c8\ub098 \uc911\uc694\ud558\uac8c \uc5ec\uaca8\uc57c \ud560\uae4c**\n\n**\uc804\ud600 \uc911\uc694\ud558\uac8c \uc5ec\uae38 \ud544\uc694\uac00 \uc5c6\ub2e4.** \uc774\ub4e4\uc740 \ub300\uaddc\ubaa8 \ubb3c\ub7c9\uc73c\ub85c \uac70\ub798\ud558\uae30 \ub54c\ubb38\uc5d0 \uc8fc\uac00\uc5d0 \uc601\ud5a5\uc744 \ubbf8\uce60 \uc218\ub294 \uc788\uc73c\ub098 \ub2e8\uae30\uc801\uc73c\ub85c \uadf8\ub7f4 \ubfd0\uc774\ub2e4. \uc5b4\ub290 \uae30\uad00\uc774 \ud2b9\uc815 \uc8fc\uc2dd\uc744 \ub300\ub7c9\uc73c\ub85c \uc0ac\uac70\ub098 \ud314\uba74 \uba70\uce60 \ub3d9\uc548 \uc8fc\uac00\ub294 \uc624\ub974\uac70\ub098 \ub0b4\ub9b0\ub2e4. \ud558\uc9c0\ub9cc \uc7a5\uae30\uc801\uc73c\ub85c\ub294 \uc544\ubb34 \uc601\ud5a5\ub3c4 \ub07c\uce58\uc9c0 \uc54a\ub294\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 49\n\n**\uc804\ubb38\uac00\uc758 \ucd94\ucc9c\uc740 \uc7a5\uae30\uc801\uc73c\ub85c \uc5bc\ub9c8\ub098 \uc911\uc694\ud558\uac8c \uc5ec\uaca8\uc57c \ud560\uae4c**\n\n**\uc911\uc694\ud558\uac8c \uc5ec\uae38 \ud544\uc694\uac00 \uc804\ud600 \uc5c6\ub2e4.** \uc0b0\uc5c5 \ubd84\uc57c\ub098 \uae30\uc5c5\uc758 \uc804\ubb38\uac00\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uc0dd\ub9ac\ub97c \uc804\ud600 \ubaa8\ub978\ub2e4. \uadf8\ub4e4\uc774 \uc5b4\ub5a4 \uae30\uc5c5\uc744 \uc870\uc0ac\ud55c \ub0a0 \uadf8 \uae30\uc5c5\uc758 \uc0c1\ud669\uc740 \uc54c \uc218 \uc788\ub2e4. \ud558\uc9c0\ub9cc \uc5b4\uc81c \uc720\ud6a8\ud588\ub358 \uac83\uc774 \uc624\ub298\uc740 \uc720\ud6a8\ud558\uc9c0 \uc54a\uc744 \uc218\ub3c4 \uc788\ub2e4. **\uc8fc\uc2dd\uc2dc\uc7a5\uc5d0\uc11c\ub294 \ud56d\uc0c1 \uc0c8\ub85c \uc0dd\uac01\ud574 \ub0b4\uc57c \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 50\n\n**\uae30\uc5c5 \ub0b4\ubd80\uc790\uc758 \ucd94\ucc9c\uc740 \uc5bc\ub9c8\ub098 \ubbff\uc5b4\uc57c \ud560\uae4c**\n\n**\uc804\ud600 \ubbff\uc9c0 \ub9d0\ub77c.** \ub0b4\ubd80\uc790\ub294 \uadf8 \uae30\uc5c5\uc758 \uc81c\ud488 \ubc1c\uc804 \uac00\ub2a5\uc131\uc5d0 \ub300\ud574\uc11c\ub294 \uc798 \uc548\ub2e4. \ud558\uc9c0\ub9cc \uc790\ubcf8\uc2dc\uc7a5 \uc804\uccb4\uc640 \uc790\ubcf8\uc2dc\uc7a5\uc758 \uc804\uac1c\uc640\ub294 \uc544\ubb34 \uc0c1\uad00\uc774 \uc5c6\ub2e4.\n\n> \ub0b4 \uacbd\ud5d8\uc5d0 \ub530\ub974\uba74 \ud68c\uc0ac \ub0b4\ubd80\uc790\uac00 \ucd94\ucc9c\ud558\ub294 \uac83\uacfc \uac70\uc758 \ubc18\ub300\ub85c \ud574\uc57c \ud55c\ub2e4. \ub0b4\ubd80\uc790\ub294 \uc885\uc885 \ub300\uc911\uc744 \ud63c\ub780\uc2dc\ud0a4\uae30 \uc704\ud574 \uc77c\ubd80\ub7ec \ud2c0\ub9b0 \uc815\ubcf4\ub97c \ud758\ub9b0\ub2e4. \ub0b4\uac00 \ub0b4\ubd80\uc790 \uc815\ubcf4\uc640 \uad00\ub828\ud574 \uacaa\uc740 \uc218\uc2ed \ubc88\uc758 \uacbd\ud5d8 \ubaa8\ub450 \uc190\uc2e4\ub85c \uc9c1\uacb0\ub418\uc5b4 \uc788\uc5c8\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 51\n\n**\uacbd\uc81c \uc804\ubb38\uac00\uc640 \uacbd\uc81c\ud559\uc790\ub4e4\uc758 \ubc1c\uc804 \uc804\ub9dd\uc740 \uc5bc\ub9c8\ub098 \ubbff\uc5b4\uc57c \ud560\uae4c**\n\n**\uc5ed\uc2dc \ud06c\uac8c \ubbff\uc744 \ud544\uc694\uac00 \uc5c6\ub2e4.** \ucd5c\uace0\uc758 \uacbd\uc81c\ud559\uc790\ub3c4 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ucd94\uc138\ub97c \uc815\ud655\ud788 \ubd84\uc11d\ud558\uc9c0 \ubabb\ud55c\ub2e4. \uc8fc\uc2dd\uc2dc\uc7a5\uacfc \uacbd\uc81c\ub294 \ub098\ub780\ud788 \uac00\uc9c0 \uc54a\ub294\ub2e4.\n\n> \uacbd\uc81c\ud559\uc790\ub294 \uacbd\uc81c\uc640 \ub3c8\uc5d0 \ub300\ud574\uc11c \ubaa8\ub4e0 \uac83\uc744 \uc548\ub2e4. \ud558\uc9c0\ub9cc \ub3c8\uc744 \uac00\uc9c0\uace0 \uc788\uc9c0\ub294 \uc54a\ub2e4.\n\n\uacbd\uc81c \ubd88\ud669\uc740 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \ubd88\ub9ac\ud558\uace0, \uacbd\uc81c \ud638\ud669\uc740 \uc8fc\uc2dd\uc2dc\uc7a5\uc5d0 \uc720\ub9ac\ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 52\n\n**\uacbd\uc81c\uc640 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \ud56d\uc0c1 \uc5f0\ub3d9\ub418\ub294\uac00**\n\n\ud56d\uc0c1\uc740 \uc544\ub2c8\uc9c0\ub9cc \ub300\ubd80\ubd84 \uadf8\ub807\ub2e4. **\uacbd\uc81c\uc640 \uc8fc\uc2dd\uc2dc\uc7a5\uc740 \uacb0\uad6d \uc5f0\uad00\uc774 \uc788\uc9c0\ub9cc, \ub098\ub780\ud788 \uac00\ub294 \uac83\uc774 \uc544\ub2c8\ub77c \uc2dc\uac04\ucc28\ub97c \ub450\uace0 \uc9c4\ud589\ub41c\ub2e4.** \ub300\ubd80\ubd84 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \ucd94\uc138\ub294 \uc55e\uc73c\ub85c \ub2e4\uac00\uc62c \uacbd\uc81c \ubc1c\uc804\uc5d0 \uc55e\uc120\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 53\n\n**\uc0ac\uc5c5\ubcf4\uace0\uc11c\u00b7\uc8fc\uc8fc\ucd1d\ud68c \ubc1c\ud45c \ub4f1\uc774 \ucda9\ubd84\ud55c \uc815\ubcf4\uc778\uac00**\n\n\uc544\ub2c8\ub2e4. **\ud589\uac04\uc744 \uc77d\uc744 \uc904 \uc54c\uc544\uc57c \ud55c\ub2e4.** \uadf8\ub9ac\uace0 \ubaa8\ub4e0 \ubc1c\ud45c\ub098 \ub274\uc2a4 \ub4a4\uc5d0 \ubb34\uc2a8 \uc77c\uc774 \uc9c4\uc9dc \uc228\uc5b4 \uc788\ub294\uc9c0, \ubcf4\ub3c4\uac00 \ud2c0\ub9ac\uc9c0 \uc54a\uc558\ub294\uc9c0 \ud639\uc740 \uacfc\uc7a5\ub418\uac70\ub098 \ucd95\uc18c\ub418\uc9c0 \uc54a\uc558\ub294\uc9c0 \uc0dd\uac01\ud574\uc57c \ud55c\ub2e4. **\ub274\uc2a4\ub098 \ubc1c\ud45c\ub294 \uc544\uc8fc \ube44\ud310\uc801\uc73c\ub85c, \uc2ec\uc9c0\uc5b4 \ud68c\uc758\uc801\uc73c\ub85c \ubd84\uc11d\ud574\uc57c \ud55c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 54\n\n**\ub300\ucc28\ub300\uc870\ud45c\u00b7\ubc30\ub2f9\uae08 \ub4f1\uc5d0 \ub300\ud574 \uc790\uc138\ud55c \uc0c1\ud669\uc744 \uc54c\uc544\uc57c \ud558\ub294\uac00**\n\n**\uc138\uc138\ud55c \uac83\uc744 \ub108\ubb34 \ub9ce\uc774 \uc54c\uba74 \uc804\uccb4\uc5d0 \ub300\ud55c \uc870\ub9dd\uc744 \uc783\uc5b4\ubc84\ub9b0\ub2e4.** \ub098\ubb34 \uc55e\uc5d0 \uc11c\uba74 \uc232\uc774 \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac83\uacfc \uac19\uc774. \ud22c\uc790\uc790\ub294 \uc801\uac8c \uc54c\ub418 \ubaa8\ub4e0 \uac83\uc744 \uc774\ud574\ud560 \uc218 \uc788\uc5b4\uc57c \ud55c\ub2e4. \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c \ud544\uc694\ud55c \uc9c0\uc2dd\uc740 \ubaa8\ub4e0 \uc138\uc138\ud55c \uac83\uc744 \ub2e4 \uc78a\uc5b4\ubc84\ub9ac\uace0 \ub0a8\uc740 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 55\n\n**\uc804\ubb38\uac00 \ubd84\uc11d\uc740 \ub0b4\ubd80\uc790 \uc815\ubcf4\uc758 \uacbd\uc6b0\uc640 \ube44\uc2b7\ud55c\uac00**\n\n\uc5b4\ub290 \uc815\ub3c4\ub294 \uadf8\ub807\ub2e4. **\uc5d4\uc9c0\ub2c8\uc5b4, \ubc1c\uba85\uac00, \uae30\uc220\uc790, \uacfc\ud559\uc790, \uc7ac\uc815 \uc804\ubb38\uac00, \uc2ec\uc9c0\uc5b4 \uae30\uc5c5 \uacbd\uc601\uc790\ub3c4 \uc8fc\uc2dd \uc2dc\uc138\uac00 \uc5b4\ub5a8\uc9c0 \uc9c4\ub2e8\ud558\ub294 \uc0ac\ub78c\uc73c\ub85c\ub294 \uc801\ub2f9\ud558\uc9c0 \uc54a\ub2e4.** \uc774\ub4e4\uc740 \ub108\ubb34 \ub9ce\uc774 \uc548\ub2e4. \ub108\ubb34 \ub9ce\uc774 \uc54c\uba74 \uc0c1\uc0c1\ub825\uc5d0 \uc81c\ub3d9\uc774 \uac78\ub9ac\uae30 \ub54c\ubb38\uc5d0 \uc99d\uad8c\uc2dc\uc7a5\uc5d0\uc11c\ub294 \uc624\ud788\ub824 \ud574\ub86d\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 56\n\n**\ud22c\uc790\uc790\uc5d0\uac8c \uac00\uc7a5 \uc704\ud5d8\ud55c \uac83\uc740 \ubb34\uc5c7\uc778\uac00**\n\n**\ubc18\ub9cc \uc633\uc740 \uc815\ubcf4\uac00 \uac00\uc7a5 \uc704\ud5d8\ud558\ub2e4.** \ubc18\ub9cc \uc633\uc740 \uc815\ubcf4\ub294 100% \ud2c0\ub9b0 \uc815\ubcf4\ubcf4\ub2e4 \ub354 \uc704\ud5d8\ud558\ub2e4. \ub2e8\uc5b4\uc758 \uc9c4\uc2e4\uc740 \uc644\uc804\ud55c \uac70\uc9d3\ub9d0\uc774\uae30 \ub54c\ubb38\uc774\ub2e4. \ud2c0\ub9b0 \uc815\ubcf4\ub97c \uc811\ud558\uba74 \ud22c\uc790\uc790\ub294 \ube44\ud310\uc801\uc73c\ub85c \uc0dd\uac01\ud55c\ub2e4. \ud558\uc9c0\ub9cc **\uac00\uc7a5 \uc704\ud5d8\ud55c \uac83\uc740 \uc633\uc740 \uc815\ubcf4\ub97c \uc798\ubabb \ud574\uc11d\ud558\ub294 \uac83\uc774\ub2e4.** \uc774\ub294 \uc798\ubabb\ub41c \uc0dd\uac01\uc758 \uacb0\uacfc\uc774\uace0, \ub300\uc0c1\uc5d0 \ub300\ud55c \uc9c0\uc2dd\uc774 \ubaa8\uc790\ub77c\uae30 \ub54c\ubb38\uc774\uae30\ub3c4 \ud558\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 57\n\n**\uac11\uc790\uae30 \ud070\ub3c8\uc774 \uc0dd\uae30\uba74 \uc5b4\ub5bb\uac8c \ub418\ub294\uac00**\n\n\uc5b4\ub5a4 \uc0ac\ub78c\uc774 \uac11\uc790\uae30 \ud070\ub3c8\uc744 \uac16\uac8c \ub418\uba74 \uc774\uc131\uc744 \uc783\uace0, \uc5b4\ub5bb\uac8c \ud558\uba74 \uc778\ud50c\ub808\uc774\uc158\uc5d0\uc11c \uadf8 \ub3c8\uc744 \uc9c0\ud0ac \uc218 \uc788\uc744\uc9c0, \uc138\ubb34\uc11c\uc5d0\ub294 \uc5b4\ub5bb\uac8c \uc228\uae38\uc9c0, \uadf8\ub9ac\uace0 \uac00\uc7a5 \uc911\uc694\ud558\uac8c\ub294 \uc5b4\ub5bb\uac8c \ub3c8\uc744 \ubd88\ub9b4\uc9c0 \uace0\ubbfc\ud558\ub290\ub77c \uadf9\ub3c4\ub85c \uc608\ubbfc\ud574\uc9c4\ub2e4. \uc7ac\ud14c\ud06c \ube44\ubc95\uc5d0 \uadc0\ub97c \uae30\uc6b8\uc774\uba70 \uc5ec\uae30\uc800\uae30 \ud5e4\ub9e4\uace0 \ub2e4\ub2cc\ub2e4. **\uc774\ub7f0 \ub300\uc911\uc744 \uc870\uc791\ud558\uae30\ub780 \uadf8\uc57c\ub9d0\ub85c \uc2dd\uc740 \uc8fd \uba39\uae30\ub2e4.**\n\n\uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc0c1\uc2b9\ud558\uba74 \uc218\ucc9c \uba85\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub2a6\uc9c0 \uc54a\uc73c\ub824\uace0 \ub108\ub3c4\ub098\ub3c4 \ub2ec\ub9ac\ub294 \uae30\ucc28\uc5d0 \ub6f0\uc5b4\uc624\ub978\ub2e4. \ub300\uc911\uc73c\ub85c\uc11c\ub294 \uc8fc\uc2dd\uc2dc\uc7a5\uc774 \uc808\uc815\uc5d0 \ub2ec\ud588\ub294\ub370 \uc8fc\uc2dd \ud558\ub098 \uc5c6\uc774 \uadf8 \uc7a5\uba74\uc744 \uc9c0\ucf1c\ubcf4\uace0 \uc788\uc5b4\uc57c \ud55c\ub2e4\uba74 \ucc38\uc73c\ub85c \uace0\ud1b5\uc2a4\ub7ec\uc6b4 \uc77c\uc77c \uac83\uc774\ub2e4. \uc5b4\uca4c\uba74 \uc8fc\uc2dd\uc744 \uc0b0 \ud6c4 \uc190\ud574\ub97c \ubcf4\ub294 \uac83\ubcf4\ub2e4 \ub354 \uace0\ud1b5\uc2a4\ub7ec\uc6b8 \uac83\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 58\n\n**\uc740\ud589\uacfc \uae08\uc735\uae30\uad00\uc740 \ub300\uc911\uc5d0\uac8c \uc815\uc9c1\ud558\uc9c0 \uc54a\ub2e4\ub294 \ub73b\uc778\uac00**\n\n\uc544\ub2c8\ub2e4. \uc815\uc9c1\ud558\uc9c0 \uc54a\uc740 \uac83\uc740 \uc808\ub300\ub85c \uc544\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \uc885\uc885 \ucc45\uc784\uac10 \uc5c6\uc774 \ud589\ub3d9\ud558\uae30\ub294 \ud55c\ub2e4. **\uc740\ud589\uacfc \uae08\uc735\uae30\uad00\ub3c4 \uc774\uc724 \ucc3d\ucd9c \uae30\uc5c5\uc774\ub2e4.** \uadf8\ub807\ub2e4\uace0 \ud574\uc11c \ub300\uc911\uc744 \uae30\ub9cc\ud55c\ub2e4\uace0 \ud560 \uc218\ub294 \uc5c6\ub2e4. \uc2dd\ub2f9 \uc8fc\uc778\uc774 \uc5b4\ub5a4 \uc74c\uc2dd\uc744 \uadf8\ub0a0 \uc548\uc73c\ub85c \uc5c6\uc560\ubc84\ub9ac\uace0 \uc2f6\uc5b4\uc11c \ud2b9\ubcc4\ud788 \uadf8 \uc74c\uc2dd\uc744 \ucd94\ucc9c\ud55c\ub2e4\uace0 \ud574\uc11c \uadf8\uac00 \uc815\uc9c1\ud558\uc9c0 \uc54a\ub2e4\uace0 \ub9d0\ud560 \uc218\ub294 \uc5c6\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 59\n\n**\uc2dc\uc138\uac00 \ub5a8\uc5b4\uc838\uc11c \ub300\uc911\uc774 \ub3c8\uc744 \uc783\uac8c \ub418\uba74 \uacbd\uc81c\uc5d0 \ub098\uc05c\uac00**\n\n\uc5b4\ub290 \uc815\ub3c4\uae4c\uc9c0\ub294 \uadf8\ub807\ub2e4. \uc8fc\uc2dd\uc758 \uc5ed\uc0ac\ub97c \ubcf4\uba74 \uc8fc\uc2dd \ubd90\uc774 \uc628 \ud6c4\uc5d0\ub294 \ud56d\uc0c1 \ud63c\ub780\uae30\uac00 \ub530\ub77c\uc654\ub2e4. \uc8fc\uc2dd\uc774 \ud3ed\ub77d\ud558\uba74\uc11c \uc218\ucc9c \uba85\uc758 \uc0ac\ub78c\ub4e4\uc774 \ub3c8\uc744 \uc783\uac8c \ub418\uc9c0\ub9cc, \uc774\ubbf8 \uc774 \ub3c8\uc758 \ub9ce\uc740 \ubd80\ubd84\uc740 \uae30\uc5c5\uc5d0\uac8c \ud758\ub7ec\ub4e4\uc5b4\uac14\ub2e4. \ubd90 \uc2dc\uae30\uc5d0\ub294 \uc218\ub9ce\uc740 \uc0c8\ub85c\uc6b4 \uae30\uc5c5\uc774 \uc0dd\uae30\uace0, \ud3ed\ub77d \ud6c4\uc5d0\ub294 \uc218\ub9ce\uc740 \uae30\uc5c5\uc774 \ub2e4\uc2dc \uc0ac\ub77c\uc9c4\ub2e4. **\ud558\uc9c0\ub9cc \uc5c6\uc5b4\uc9c0\ub294 \uae30\uc5c5\ubcf4\ub2e4 \ub9ce\uc740 \uc218\uac00 \uc0b4\uc544\ub0a8\uc544 \uacbd\uc81c \ubc1c\uc804\uc5d0 \uc911\uc694\ud55c \uc5ed\ud560\uc744 \ud558\uac8c \ub41c\ub2e4.**\n\n---\n\n## \ud3ec\uc778\ud2b8 60\n\n**\ubd88\uacbd\uae30 \ub54c \uc8fc\uc2dd\uc744 \uc0ac\uc57c \ud560\uae4c**\n\n\uadf8\ub807\ub2e4. **\ubd88\uacbd\uae30 \ub54c \uc815\ubd80\ub294 \uacbd\uc81c\ub97c \ud65c\uc131\ud654\uc2dc\ud0a4\uace0 \uae08\ub9ac\ub97c \ub0ae\ucd94\uace0 \ud1b5\ud654\ub7c9\uc744 \ub298\ub9b0\ub2e4. \uadf8\ub7ec\uba74 \uccab \ubc88\uc9f8\ub85c \uc774\ub4dd\uc744 \ubcf4\ub294 \uac83\uc774 \uc8fc\uc2dd\uc2dc\uc7a5\uc774\ub2e4. \uacbd\uc81c\ubcf4\ub2e4 \ub354 \ube68\ub9ac \ub9d0\uc774\ub2e4.** \ub3c8\uc740 \uc8fc\uc2dd\uc2dc\uc7a5\uc744 \ub3cc\uc544\uac00\uac8c \ud558\ub294 \uc0b0\uc18c\uc774\uae30 \ub54c\ubb38\uc774\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 61\n\n**\uc65c \uacbd\uc81c\ud559\uc790\ub4e4\uc744 \uadf8\ud1a0\ub85d \ube44\ud310\ud558\ub294\uac00**\n\n> \ub2f9\uc2e0\uc740 \uc544\ubb34\uac83\ub3c4 \uc78a\uc9c0 \uc54a\uace0 \uc544\ubb34\uac83\ub3c4 \ubc30\uc6b0\uc9c0 \uc54a\uc558\uad70\uc694.\n\n\ub098\ub294 \uc624\ub298\ub0a0\uc758 \uacbd\uc81c \uc804\ubb38\uac00\ub4e4\uc5d0\uac8c \ub611\uac19\uc740 \ub9d0\uc744 \ud558\uace0 \uc2f6\ub2e4. **\uadf8\ub4e4\uc740 \uc99d\uc2dc \uc9c4\ub2e8\uc740 \ub9d0\ud560 \uac83\ub3c4 \uc5c6\uace0 \uacbd\uc81c \uc9c4\ub2e8\uc5d0\ub3c4 \uc804\ud600 \uc801\ud569\ud558\uc9c0 \uc54a\ub2e4.** \ubbf8\uad6d \uc5b8\ub860\uc5d0 \ub530\ub974\uba74 \uc774\ubbf8 2\ub144 \uc804\uc5d0 \ub300\uae30\uc5c5\ub4e4\uc774 \ub2e4\uc218\uc758 \uacbd\uc81c\ud559\uc790\ub4e4\uc744 \ud574\uace0\ud588\ub2e4. \uc644\uc804\ud788 \ud2c0\ub9b0 \uc9c4\ub2e8\uc744 \ud574\uc11c \uae30\uc5c5\uc5d0 \ub9c9\ub300\ud55c \uc190\ud574\ub97c \ub07c\ucce4\uae30 \ub54c\ubb38\uc774\ub2e4. \uc778\ud50c\ub808\uc774\uc158, \uae09\ub9e4, \uae08\ub9ac \ub4f1 \uc544\ubb34\uac83\ub3c4 \ub9de\ub294 \uac83\uc774 \uc5c6\uc5c8\ub2e4.\n\n**\uadf8\ub4e4\uc758 \ubd88\ud589\uc740 \uacfc\uac70\ub098 \uc624\ub298\ub0a0\uc774\ub098 \uc0dd\uac01\ud558\uc9c0 \uc54a\uace0 \uacc4\uc0b0\ub9cc \ud55c\ub2e4\ub294 \uac83\uc774\ub2e4.** \uc5ed\uc0ac\uc0c1 \uac00\uc7a5 \uc704\ub300\ud55c \uacbd\uc81c\ud559\uc790\ub4e4, \ud1a0\ub9c8\uc2a4 \ubaa8\ub8e8\uc2a4, \uc544\ub2f4 \uc2a4\ubbf8\uc2a4, \ub370\uc774\ube44\ub4dc \ub9ac\uce74\ub3c4, \uc874 \ucf00\uc778\uc2a4 \ub4f1\uc740 \ubaa8\ub450 \uc704\ub300\ud55c \uc0ac\uc0c1\uac00\uc600\ub2e4. \uadf8\ub4e4\uc740 \uc9c4\ub2e8\uc774 \uc544\ub2c8\ub77c \uc774\ub860\uc744 \uc138\uc6b0\uace0, \uc774\ub860\uc744 \ud1b5\ud574 \uc815\ubd80\uc758 \uc815\ucc45\uc5d0 \uc601\ud5a5\uc744 \ub07c\uce58\ub824\uace0 \ud588\ub2e4.\n\n\uadf8\uc5d0 \ubc18\ud574 \uc694\uc998\uc758 \uacbd\uc81c\ud559\uc790\ub4e4\uc740 \uacbd\ub9ac\uc774\uace0 \ud1b5\uacc4\uc0ac\uc774\ub2e4. \uc22b\uc790\uc5d0 \ud604\ud639\ub418\uc5b4 \uadf8 \ub4a4\uc5d0 \ubb34\uc5c7\uc774 \uc228\uaca8\uc838 \uc788\ub294\uc9c0 \uc5f0\uad6c\ud558\uc9c0 \uc54a\ub294\ub2e4.\n\n> \ub098\ub294 \ub0b4\uac00 \uc870\uc791\ud55c \uc22b\uc790\ub9cc \ubbff\ub294\ub2e4. \u2014 \uc708\uc2a4\ud134 \ucc98\uce60\n\n**\uacbd\uc81c\uc640 \uae08\uc735\uc758 \uac00\uc7a5 \uc911\uc694\ud55c \uc694\uc18c\ub294 \ub2e8 \ud55c \uac00\uc9c0, \uc2ec\ub9ac\ub77c\ub294 \uc0ac\uc2e4\uc744 \uc78a\uc5b4\ubc84\ub9ac\uace0 \uc788\ub2e4.** \uc2e0\ub8b0\uac00 \uc5c6\uc73c\uba74 \ubaa8\ub4e0 \uac83\uc774 \uc2e4\ud328\ub85c \ub3cc\uc544\uac00\uace0, \uc2e0\ub8b0\uac00 \uc788\uc73c\uba74 \ubaa8\ub4e0 \ubb38\uc81c\ub97c \ud480 \uc218 \uc788\ub2e4.\n\n---\n\n## \ud3ec\uc778\ud2b8 62\n\n**\uc790\ubcf8\uc8fc\uc758 \uc2dc\uc2a4\ud15c\uc5d0 \ub300\ud55c \ucd5c\uc885 \uacac\ud574**\n\n> \uc804\uccb4\uc758 \ubcf5\uc9c0\ub294 \uac70\uc9d3\ub9d0\uacfc \ubc30\uc2e0\uc744 \uc694\uad6c\ud55c\ub2e4. \u2014 \ubbf8\uc178 \ub4dc \ubabd\ud14c\ub274\n\n**\uc790\ubcf8\uc8fc\uc758 \uc2dc\uc2a4\ud15c \uc804\uccb4\ub294 \ud558\ub098\uc758 \ud658\uc0c1, \uc18d\uc784\uc218\uc774\ub2e4. \ud558\uc9c0\ub9cc \uc544\uc8fc \uc798 \ub9cc\ub4e4\uc5b4\uc9c4 \ud658\uc0c1\uc774\ub2e4. \uc624\ub7ab\ub3d9\uc548 \uc874\uc7ac\ud560 \uac83\uc774\ub2e4.**\n\n---\n\n## \ub9fa\uc74c\ub9d0\n\n\ub098\ub294 \uc5ec\ub7ec\ubd84\ub4e4\uc5d0\uac8c \ub0b4\uac00 \uc54c\uace0 \uc788\ub294 \uc6d0\uce59\uc744 \uc804\ud574\uc8fc\uc5c8\ub2e4. \uc5b4\ub5bb\uac8c \ud589\ub3d9\ud574\uc57c \ud560\uc9c0 \uc0dd\uac01\ud558\ub294 \uac83\uc740 \uc5ec\ub7ec\ubd84\ub4e4\uc758 \ubaab\uc774\ub2e4.\n\n> \uc778\uc0dd\uc774\ub098 \uc8fc\uc2dd\uc774\ub098, \ub2e4\ub978 \uc0ac\ub78c\uc5d0\uac8c \uae4a\uc774 \uc0dd\uac01\ud560 \uacc4\uae30\ub97c \ub9c8\ub828\ud574 \uc8fc\ub294 \uac83\ubcf4\ub2e4 \ub354 \uc911\uc694\ud558\uace0 \uc720\uc775\ud55c \uc77c\uc740 \uc5c6\uc744 \uac83\uc774\ub2e4.\n\n\uc790\uae30 \uba38\ub9ac\ub97c \uc950\uc5b4\uc9dc\ub294 \uac83\ubcf4\ub2e4 \uc0c1\ub2f4\uc0ac\ub098 \uc8fc\uc2dd \uc804\ubb38\uac00 \ud639\uc740 \uc5b8\ub860\uc744 \ub530\ub974\uace0 \uc2f6\uc740 \ub9c8\uc74c\uc774 \uad74\ub69d\uac19\ub2e4\ub294 \uac83\uc740 \ub098\ub3c4 \uc798 \uc548\ub2e4. **\uadf8\ub798\ub3c4 \ud63c\uc790 \ub098\ub984\ub300\ub85c \uc0dd\uac01\ud574 \ubcf4\ub77c. \uadf8\ub7ec\uba74 \uac70\uae30\uc5d0\uc11c \uc9c4\uc815\ud55c \uc990\uac70\uc6c0\uc744 \ub9db\ubcfc \uc218 \uc788\uc744 \uac83\uc774\ub2e4.** \ub9c8\uce58 \uce74\ub4dc \uac8c\uc784\uc744 \ud558\ub294 \uc0ac\ub78c\uc774 \uc5b4\ub5a4 \uce74\ub4dc\ub97c \ub0b4\uc57c \ud560\uc9c0 \uc2a4\uc2a4\ub85c \uacb0\uc815\ud574\uc57c \ud560 \ub54c \uc7ac\ubbf8\ub97c \ub290\ub07c\ub294 \uac83\ucc98\ub7fc \ub9d0\uc774\ub2e4.\n\n> \uc9c0\uc2dd\uc740 \ub204\uad6c\ub098 \uac00\uc9c8 \uc218 \uc788\ub294 \uac83\uc774\uc9c0\ub9cc, \uc0dd\uac01\ud558\ub294 \uc7ac\uc8fc\ub294 \ud754\uce58 \uc54a\uc740 \uc790\uc5f0\uc758 \uc120\ubb3c\uc774\ub2e4. \u2014 \ud504\ub9ac\ub4dc\ub9ac\ud788 \ub300\uc655\n\n**\uc77c\ubc18\uc801\uc778 \uacac\ud574\ub97c \ubb34\uc2dc\ud558\uace0 \ud22c\uc790\ub97c \ud574\uc11c \uc790\uc2e0\uc758 \ud589\ub3d9\uc774 \uc633\uc558\uc74c\uc744 \uc778\uc815\ubc1b\uc744 \ub54c\ubcf4\ub2e4 \ub354 \uc9dc\ub9bf\ud55c \uc21c\uac04\uc740 \uc5c6\ub2e4.**\n\n\uc8fc\uc2dd\uc5d0\uc11c\ub294 2 \uacf1\ud558\uae30 2\ub294 4\uac00 \uc544\ub2c8\ub77c 5 \ube7c\uae30 1\uc774\ub2e4. \ub9d0\ud558\uc790\uba74 \uacb0\uacfc\ub294 \ud56d\uc0c1 \uc790\uc2e0\uc774 \uae30\ub300\ud588\ub358 \uac83\uacfc \ub2e4\ub974\uac8c \ub098\ud0c0\ub098\uace0, \ub098\uc911\uc5d0\uc57c \ube44\ub85c\uc18c \uc608\uc0c1\ud588\ub358 \ub300\ub85c \uac04\ub2e4. **\uacb0\uad6d\uc5d0\ub294 \ub17c\ub9ac\uac00 \uc2b9\ub9ac\ub97c \uac70\ub450\uae30 \ub9c8\ub828\uc774\uae30\uc5d0, \uadf8 \uacfc\uc815\uc758 \uace0\ud1b5\uc744 \uae30\ub2e4\ub9b4 \uc218 \uc788\ub294 \uc778\ub0b4\uac00 \uc788\uc5b4\uc57c \ud55c\ub2e4.** \ud22c\uc790\uc790 \uac00\uc6b4\ub370 10%\ub9cc\uc774 \uadf8 \uce58\uba85\uc801\uc778 \uacfc\uc815\uc744 \uadf9\ubcf5\ud560 \uc218 \uc788\ub2e4.\n\n> \ud22c\uc790\uc790\ub294 \ub300\ubd80\ubd84 \uc778\ub0b4\uc2ec, \ub3c8 \ud639\uc740 \ud655\uc2e0\uc774 \ubd80\uc871\ud558\ub2e4. \uadf8\ub807\uae30 \ub54c\ubb38\uc5d0 \ub098\ub294 \uc8fc\uc2dd\uc73c\ub85c \uc0dd\uae30\ub294 \ub3c8\uc740 \uace0\ud1b5\uc758 \ub3c8\uc774\ub77c\uace0 \ub298 \ub418\ud480\uc774\ud574 \ub9d0\ud55c\ub2e4. \uba3c\uc800 \uace0\ud1b5\uc744 \uacaa\uace0 \ub098\uc57c \ub3c8\uc774 \uc0dd\uae30\ub294 \uac83\uc774\ub2e4.\n\n\ud2b9\ud788 \uc559\ub4dc\ub808 \ucf54\uc2a4\ud1a8\ub77c\ub2c8 \ucd1d\uc11c 1\u00b72\u00b73\uad8c\uc744 \uaf2d \uc0ac\uc11c \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ud55c\ub2e4. \uc138 \uad8c\uc744 \ubc18\ubcf5\ud574\uc11c \uc77d\uc5b4 \ubcf4\uc2e0\ub2e4\uba74 \ubd84\uba85\ud788 \uc8fc\uc2dd\uc2dc\uc7a5\uc758 \uac10\uc744 \uc7a1\uc744 \uc218 \uc788\uc744 \uac83\uc774\ub2e4.\n"
